insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Compõem o Sistema Nacional de Trânsito o Contran, coordenador do Sistema e órgão máximo normativo e consultivo; os Conselhos Estaduais de Trânsito e o do Distrito Federal; os órgãos e entidades executivos de trânsito da União, dos Estados, do Distrito Federal e dos Municípios; os órgãos executivos rodoviários; a Polícia Rodoviária Federal; as Polícias Militares; as Juntas Administrativas de Recursos de Infrações; e as Câmaras Temáticas, entre outros.', '["Contran como órgão máximo normativo e consultivo.","Cetran e Contrandife.","Órgãos executivos de trânsito e rodoviários.","Polícia Rodoviária Federal, Polícias Militares e JARI."]'::jsonb, '["Contran é o órgão máximo NORMATIVO e consultivo.","ATUALIZAÇÃO: a composição do sistema foi alterada por leis posteriores; consulte o texto vigente."]'::jsonb, 'O Contran edita as resoluções que regulamentam o Código.', '["Assertiva que atribui ao Detran a função de órgão máximo normativo erra: é do Contran."]'::jsonb, '[{"termo":"Contran","significado":"Conselho Nacional de Trânsito, órgão máximo normativo e consultivo do sistema."}]'::jsonb, '["Art. 12"]'::jsonb, 'under_review', 'claude'
