insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Contran tem sede no Distrito Federal e é composto por Ministros de Estado responsáveis por áreas definidas em lei, como ciência e tecnologia, educação, defesa, meio ambiente, saúde, justiça e relações exteriores, entre outras. Vários incisos foram revogados ou alterados por leis posteriores.', '["Sede no Distrito Federal.","Composto por Ministros de Estado.","Incisos alterados ou revogados por leis posteriores."]'::jsonb, '["ATUALIZAÇÃO: a composição do Contran foi reorganizada; confira o texto vigente.","É composto por Ministros de Estado."]'::jsonb, 'O Contran reúne representantes de várias pastas ministeriais.', '["Assertiva que compõe o Contran com representantes estaduais erra: é composto por Ministros de Estado."]'::jsonb, '[]'::jsonb, '["Art. 12"]'::jsonb, 'under_review', 'claude'
