insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Compete ao Contran estabelecer as normas regulamentares do Código e as diretrizes da Política Nacional de Trânsito; coordenar os órgãos do Sistema; criar Câmaras Temáticas; fixar seu regimento e as diretrizes de funcionamento dos Cetran e do Contrandife e das JARI; zelar pela uniformidade das normas; normatizar o enquadramento das condutas, a fiscalização, as penalidades e a arrecadação das multas; responder a consultas; normatizar aprendizagem, habilitação, documentos de condutores, registro e licenciamento de veículos; aprovar a sinalização e os equipamentos de trânsito; avocar processos sobre conflitos de competência; dirimir conflitos de circunscrição; e normatizar o processo de formação do candidato à CNH, com conteúdo, carga horária, avaliações e exames. As propostas de normas regulamentares passam por consulta pública de, no mínimo, 30 dias. Em urgência, o presidente pode editar deliberação ad referendum do Plenário, que perde eficácia se não aprovada em 120 dias, mantidos os efeitos já produzidos.', '["Normas regulamentares e diretrizes da política de trânsito.","Câmaras Temáticas e regimentos dos Cetran e JARI.","Normatizar habilitação, registro, licenciamento e formação do candidato.","Consulta pública de, no mínimo, 30 dias.","Deliberação ad referendum perde eficácia em 120 dias se não aprovada."]'::jsonb, '["ATUALIZAÇÃO: o inciso XV (formação do candidato) e as regras de consulta pública e deliberação ad referendum vieram de leis posteriores.","Consulta pública de no mínimo 30 dias para normas regulamentares.","Deliberação ad referendum: perde eficácia em 120 dias, mantidos os efeitos."]'::jsonb, 'A resolução que padroniza a sinalização vem do Contran.', '["Assertiva que atribui ao Detran a edição das normas regulamentares do Código erra."]'::jsonb, '[]'::jsonb, '["Art. 7º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-12'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As Câmaras Temáticas, órgãos técnicos vinculados ao Contran, são integradas por especialistas e têm por objetivo estudar e oferecer sugestões e embasamento técnico sobre assuntos específicos para as decisões do Contran. Cada Câmara é constituída por especialistas representantes de órgãos executivos da União, dos Estados, do Distrito Federal e dos Municípios, em igual número.', '["Órgãos técnicos vinculados ao Contran.","Integradas por especialistas.","Composição paritária entre os entes."]'::jsonb, '["Função de assessoramento técnico, sem poder decisório."]'::jsonb, 'Uma Câmara Temática estuda a segurança de motocicletas e sugere ao Contran.', '["Assertiva que dá poder normativo final às Câmaras Temáticas erra."]'::jsonb, '[]'::jsonb, '["Art. 12"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-13'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Compete aos Cetran e ao Contrandife cumprir e fazer cumprir a legislação de trânsito; elaborar normas no âmbito de suas competências; responder a consultas; estimular campanhas educativas; julgar os recursos interpostos contra decisões das JARI e dos órgãos executivos estaduais nos casos de inaptidão permanente constatada nos exames de aptidão física, mental ou psicológica; indicar representante para a comissão que examina candidatos com deficiência física; acompanhar e coordenar as atividades de trânsito no Estado, reportando-se ao Contran; dirimir conflitos de circunscrição entre Municípios; informar o Contran sobre o cumprimento do art. 333; e designar junta especial de saúde nos recursos deferidos. Das decisões do Cetran nos recursos do inciso V não cabe recurso na esfera administrativa.', '["Normas e consultas no âmbito estadual ou distrital.","Julga recursos contra decisões das JARI.","Julga recursos de inaptidão permanente nos exames de aptidão.","Dirime conflitos de circunscrição entre Municípios.","Sem recurso administrativo contra as decisões do inciso V."]'::jsonb, '["Cetran julga recursos contra decisões das JARI e nos casos de inaptidão permanente.","Das decisões do inciso V NÃO cabe recurso administrativo.","Suas normas valem no âmbito estadual ou distrital."]'::jsonb, 'O Cetran responde a consultas sobre a aplicação da legislação no estado.', '["Assertiva que atribui ao Cetran a edição de normas nacionais erra: suas normas valem no âmbito estadual."]'::jsonb, '[]'::jsonb, '["Art. 16"]'::jsonb, 'under_review', 'claude'
