insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os presidentes dos Cetran e do Contrandife são nomeados pelos Governadores dos Estados e do Distrito Federal e devem ter reconhecida experiência em matéria de trânsito. Os membros desses órgãos também são nomeados pelos Governadores e devem ser pessoas de reconhecida experiência em trânsito.', '["Nomeação pelos Governadores.","Reconhecida experiência em trânsito."]'::jsonb, '["Quem nomeia é o Governador."]'::jsonb, 'O Governador nomeia o presidente do Cetran.', '["Assertiva que atribui ao Presidente da República a nomeação dos membros do Cetran erra."]'::jsonb, '[]'::jsonb, '["Art. 14"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-15'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Junto a cada órgão ou entidade executivo de trânsito ou rodoviário funcionam as Juntas Administrativas de Recursos de Infrações, as JARI, órgãos colegiados responsáveis pelo julgamento dos recursos interpostos contra as penalidades por eles impostas. As JARI têm regimento próprio, observadas as diretrizes do Contran, e apoio administrativo e financeiro do órgão junto ao qual funcionam.', '["JARI junto a cada órgão executivo.","Colegiado que julga recursos contra penalidades.","Regimento próprio e apoio do órgão."]'::jsonb, '["A JARI é a primeira instância recursal administrativa."]'::jsonb, 'O condutor multado recorre à JARI do órgão que o autuou.', '["Assertiva que atribui ao Contran o julgamento de recursos de multas em primeira instância erra."]'::jsonb, '[{"termo":"JARI","significado":"Junta Administrativa de Recursos de Infrações."}]'::jsonb, '["Art. 17"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-16'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Compete às JARI julgar os recursos interpostos pelos infratores; solicitar aos órgãos de trânsito e rodoviários informações complementares relativas aos recursos; e encaminhar aos órgãos informações sobre problemas observados nas autuações e apontados em recursos, para as providências cabíveis.', '["Julgar recursos.","Solicitar informações complementares.","Encaminhar informações sobre problemas nas autuações."]'::jsonb, '["Também funcionam como fonte de retroalimentação aos órgãos."]'::jsonb, 'A JARI aponta ao órgão um erro recorrente em autuações.', '["Assertiva que impede a JARI de solicitar informações complementares erra."]'::jsonb, '[]'::jsonb, '["Art. 16"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-17'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Compete ao órgão máximo executivo de trânsito da União cumprir e fazer cumprir a legislação de trânsito e a execução das normas e diretrizes do Contran; supervisionar, coordenar e fiscalizar os órgãos delegados e a execução da Política Nacional de Trânsito; articular-se com os órgãos dos demais entes; entre outras atribuições relativas a registros, estatísticas e fiscalização.', '["Cumprir as normas do Contran.","Supervisão e correição dos órgãos delegados.","Articulação com os sistemas de trânsito, transporte e segurança pública.","Manter o Renach, o Renavam e a estatística nacional de trânsito.","Administrar o fundo nacional de segurança e educação de trânsito."]'::jsonb, '["Executa e supervisiona; não edita as normas regulamentares, que são do Contran.","Mantém o Renach (habilitações) e o Renavam (veículos)."]'::jsonb, 'O órgão federal supervisiona a execução da política nacional.', '["Assertiva que dá ao órgão máximo executivo da União a função normativa do Contran erra."]'::jsonb, '[]'::jsonb, '["Art. 12"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-19'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Compete à Polícia Rodoviária Federal, no âmbito das rodovias e estradas federais, cumprir e fazer cumprir a legislação e as normas de trânsito, realizar o patrulhamento ostensivo com operações de segurança pública, executar a fiscalização de trânsito, autuar e aplicar medidas administrativas, entre outras atribuições.', '["Atuação nas rodovias e estradas federais.","Patrulhamento ostensivo.","Fiscalização, autuação e medidas administrativas."]'::jsonb, '["Âmbito: rodovias e estradas FEDERAIS."]'::jsonb, 'A PRF autua o condutor que excede a velocidade na rodovia federal.', '["Assertiva que estende a competência da PRF a todas as vias urbanas erra."]'::jsonb, '[]'::jsonb, '["Art. 21"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-20'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Compete aos órgãos e entidades executivos rodoviários da União, dos Estados, do Distrito Federal e dos Municípios, no âmbito de sua circunscrição, cumprir e fazer cumprir a legislação de trânsito, planejar, projetar, regulamentar e operar o trânsito, implantar e manter a sinalização e os equipamentos de controle viário, e executar a fiscalização, autuar e aplicar as penalidades e medidas administrativas, entre outras atribuições.', '["Planejamento e operação do trânsito nas rodovias.","Sinalização e equipamentos de controle.","Fiscalização, autuação e penalidades."]'::jsonb, '["Órgãos RODOVIÁRIOS atuam em rodovias; os executivos de trânsito, nas vias urbanas."]'::jsonb, 'O órgão rodoviário estadual sinaliza e fiscaliza a rodovia estadual.', '["Assertiva que restringe a competência dos órgãos rodoviários às vias urbanas erra."]'::jsonb, '[]'::jsonb, '["Art. 20"]'::jsonb, 'under_review', 'claude'
