on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Compete aos órgãos executivos de trânsito dos Estados e do Distrito Federal, no âmbito de sua circunscrição, cumprir a legislação, realizar e controlar o processo de formação, aperfeiçoamento, reciclagem e suspensão de condutores e expedir e cassar a Licença de Aprendizagem, a Permissão para Dirigir e a Carteira Nacional de Habilitação; vistoriar, inspecionar e registrar veículos; expedir e cassar documentos de licenciamento; e executar a fiscalização, entre outras competências.', '["Formação e habilitação de condutores.","Expedição e cassação de licença de aprendizagem, permissão e CNH.","Registro e licenciamento de veículos.","Fiscalização."]'::jsonb, '["É o órgão estadual (Detran) que habilita condutores e registra veículos.","ATUALIZAÇÃO: o rol foi alterado por leis posteriores."]'::jsonb, 'O Detran emite a CNH e registra o veículo.', '["Assertiva que atribui aos municípios a expedição da CNH erra."]'::jsonb, '[]'::jsonb, '["Art. 24"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-22'
