insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Compete aos órgãos e entidades executivos de trânsito dos Municípios, no âmbito de sua circunscrição, cumprir e fazer cumprir a legislação de trânsito, planejar, projetar, regulamentar e operar o trânsito de veículos, pedestres e animais, implantar e manter a sinalização, executar a fiscalização de trânsito, autuar e aplicar as medidas administrativas e penalidades por infrações de circulação, estacionamento e parada, entre outras atribuições.', '["Planejamento e operação do trânsito municipal.","Sinalização.","Fiscalização e penalidades por infrações de circulação, estacionamento e parada."]'::jsonb, '["O município fiscaliza as infrações de circulação, estacionamento e parada nas suas vias.","ATUALIZAÇÃO: o rol foi ampliado por leis posteriores."]'::jsonb, 'A prefeitura aplica a multa de estacionamento irregular.', '["Assertiva que restringe os órgãos municipais à sinalização, sem poder de fiscalização, erra."]'::jsonb, '[]'::jsonb, '["Art. 24-A"]'::jsonb, 'under_review', 'claude'
