insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Compete concorrentemente aos órgãos e entidades executivos de trânsito dos Estados, do Distrito Federal e dos Municípios executar a fiscalização de trânsito, autuar e aplicar as medidas administrativas e penalidades previstas no Código, observadas as competências privativas do art. 22, §2º, e do art. 24, §4º.', '["Competência concorrente para fiscalizar e autuar.","Ressalvadas as competências privativas."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior.","CONCORRENTE, com ressalva das competências privativas."]'::jsonb, 'Município e estado podem fiscalizar o trânsito, respeitadas as competências privativas.', '["Assertiva que torna exclusiva do estado toda a fiscalização erra: a competência é concorrente."]'::jsonb, '[]'::jsonb, '["Art. 22"]'::jsonb, 'under_review', 'claude'
