select u.id, u.content_sha256, 'Antes de colocar o veículo em circulação nas vias públicas, o condutor deve verificar a existência e as boas condições de funcionamento dos equipamentos de uso obrigatório, bem como assegurar-se da existência de combustível suficiente para chegar ao local de destino.', '["Verificar equipamentos obrigatórios.","Verificar combustível suficiente."]'::jsonb, '["Dever ANTES de colocar o veículo em circulação."]'::jsonb, 'O motorista confere os equipamentos e o combustível antes da viagem.', '["Assertiva que dispensa a verificação do combustível erra."]'::jsonb, '[]'::jsonb, '["Art. 28"]'::jsonb, 'under_review', 'claude'
