select u.id, u.content_sha256, 'O condutor deve, a todo momento, ter domínio de seu veículo, dirigindo-o com atenção e cuidados indispensáveis à segurança do trânsito.', '["Domínio do veículo a todo momento.","Atenção e cuidados indispensáveis."]'::jsonb, '["Princípio da direção defensiva e do domínio do veículo."]'::jsonb, 'Usar o celular a ponto de perder o domínio do veículo viola o art. 28.', '["Assertiva que dispensa atenção do condutor em vias vazias erra."]'::jsonb, '[]'::jsonb, '["Art. 29"]'::jsonb, 'under_review', 'claude'
