insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O trânsito de veículos obedece a normas como a circulação pelo lado direito, admitidas exceções sinalizadas; a distância de segurança lateral e frontal; a preferência em local não sinalizado, que é de quem circula pela rodovia, de quem circula pela rotatória e, nos demais casos, de quem vem pela direita; as faixas da direita para veículos mais lentos e de maior porte e as da esquerda para ultrapassagem; o trânsito sobre passeios e acostamentos só para entrar ou sair de imóveis; a prioridade dos veículos precedidos de batedores; e a prioridade e livre circulação dos veículos de socorro, polícia, fiscalização e ambulâncias em serviço de urgência, com alarme sonoro e luz intermitente acionados, quando todos devem liberar a faixa da esquerda e os pedestres aguardar no passeio.', '["Circulação pela direita.","Distância de segurança.","Preferência em local não sinalizado: rodovia, rotatória, depois quem vem pela direita.","Faixas da direita para os mais lentos e da esquerda para a ultrapassagem.","Prioridade e livre circulação dos veículos de urgência em serviço."]'::jsonb, '["Sem sinalização: preferência de quem circula pela rodovia ou pela rotatória; nos demais casos, de quem vem pela direita.","Alarme e luz intermitente só podem ser usados na efetiva prestação de serviço de urgência.","Passeios e acostamentos só podem ser usados para entrar ou sair de imóveis ou áreas especiais."]'::jsonb, 'O condutor mantém distância de segurança do veículo à frente.', '["Assertiva que permite circular pela esquerda como regra erra: a regra é a direita."]'::jsonb, '[]'::jsonb, '["Art. 30"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-29'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Todo condutor, ao perceber que outro que o segue tem o propósito de ultrapassá-lo, deve, se estiver na faixa da esquerda, deslocar-se para a faixa da direita, sem acelerar a marcha; e, se estiver nas demais faixas, manter-se naquela em que circula, sem acelerar. Os veículos mais lentos, quando em fila, devem manter distância suficiente entre si para permitir que os que os ultrapassem possam se intercalar na fila.', '["Quem é ultrapassado não acelera.","Faixa da esquerda: desloca-se para a direita.","Veículos lentos em fila mantêm distância."]'::jsonb, '["Quem é ultrapassado NÃO pode acelerar."]'::jsonb, 'O condutor na faixa da esquerda cede à direita ao perceber a ultrapassagem.', '["Assertiva que permite ao ultrapassado acelerar para impedir a manobra erra."]'::jsonb, '[]'::jsonb, '["Art. 32"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-30'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O condutor que tenha o propósito de ultrapassar um veículo de transporte coletivo parado, efetuando embarque ou desembarque de passageiros, deve reduzir a velocidade, dirigindo com atenção redobrada, ou parar o veículo, com vistas à segurança dos pedestres.', '["Reduzir a velocidade ou parar.","Atenção redobrada."]'::jsonb, '["Proteção do pedestre que embarca ou desembarca."]'::jsonb, 'Ao passar por um ônibus parado, o motorista reduz a velocidade.', '["Assertiva que permite ultrapassar o ônibus parado em velocidade normal erra."]'::jsonb, '[]'::jsonb, '["Art. 32"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-31'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O condutor não pode ultrapassar veículos em vias com duplo sentido de direção e pista única nos trechos em curvas e em aclives sem visibilidade suficiente, nas passagens de nível, nas pontes e viadutos e nas travessias de pedestres, exceto quando houver sinalização permitindo a ultrapassagem.', '["Proibição em curvas e aclives sem visibilidade.","Passagens de nível, pontes, viadutos e travessias de pedestres.","Exceção: sinalização permissiva."]'::jsonb, '["Exceção só com sinalização que permita."]'::jsonb, 'Ultrapassar em curva sem visibilidade é proibido.', '["Assertiva que permite ultrapassar em ponte sem sinalização erra."]'::jsonb, '[]'::jsonb, '["Art. 33"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-32'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nas interseções e suas proximidades, o condutor não pode efetuar ultrapassagem, regra que busca evitar colisões no ponto de encontro das vias.', '["Proibida ultrapassagem em interseções e proximidades."]'::jsonb, '["Proibição absoluta no texto do artigo."]'::jsonb, 'Não se ultrapassa no cruzamento.', '["Assertiva que permite a ultrapassagem em interseção se a via estiver livre erra."]'::jsonb, '[]'::jsonb, '["Art. 32"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-33'
