insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O condutor que queira executar uma manobra deve certificar-se de que pode executá-la sem perigo para os demais usuários da via que o seguem, precedem ou vão cruzar com ele, considerando sua posição, sua direção e sua velocidade.', '["Certificar-se de que a manobra é segura.","Considerar posição, direção e velocidade."]'::jsonb, '["Dever geral de cautela em manobras."]'::jsonb, 'Antes de mudar de faixa, o condutor confere o retrovisor.', '["Assertiva que dispensa a verificação dos que seguem o veículo erra."]'::jsonb, '[]'::jsonb, '["Art. 35"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-34'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Antes de iniciar qualquer manobra que implique um deslocamento lateral, o condutor deve indicar seu propósito de forma clara e com a devida antecedência, por meio da luz indicadora de direção do veículo ou fazendo gesto convencional de braço. Deslocamento lateral é a transposição de faixas, movimentos de conversão à direita ou à esquerda e retornos.', '["Sinalizar com antecedência.","Seta ou gesto de braço.","Conceito de deslocamento lateral."]'::jsonb, '["Deslocamento lateral inclui transposição de faixas, conversões e retornos."]'::jsonb, 'O condutor liga a seta antes de mudar de faixa.', '["Assertiva que dispensa a sinalização na mudança de faixa erra."]'::jsonb, '[]'::jsonb, '["Art. 34"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-35'
