insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O condutor que for ingressar numa via, procedente de um lote lindeiro a essa via, deve dar preferência aos veículos e pedestres que por ela estejam transitando.', '["Quem sai de lote lindeiro dá preferência à via."]'::jsonb, '["Preferência de quem já está na via."]'::jsonb, 'Quem sai da garagem espera passar os veículos e pedestres.', '["Assertiva que dá preferência a quem sai do lote lindeiro erra."]'::jsonb, '[]'::jsonb, '["Art. 38"]'::jsonb, 'under_review', 'claude'
