insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Antes de entrar à direita ou à esquerda, em outra via ou em lotes lindeiros, o condutor deve, ao sair pelo lado direito, aproximar-se o máximo possível do bordo direito da pista e executar a manobra no menor espaço possível; e, ao sair pelo lado esquerdo, aproximar-se o máximo possível do eixo ou da linha divisória da pista, quando houver, em pista com circulação nos dois sentidos.', '["Saída pela direita: junto ao bordo direito.","Saída pela esquerda: junto ao eixo da pista."]'::jsonb, '["Posicionamento correto antes de converter."]'::jsonb, 'Para converter à direita, o condutor se aproxima do bordo direito.', '["Assertiva que manda converter à direita partindo do eixo da pista erra."]'::jsonb, '[]'::jsonb, '["Art. 35"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-38'
