insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nas vias urbanas, a operação de retorno deve ser feita nos locais para isso determinados, por meio de sinalização ou existência de locais apropriados, ou em outros locais que ofereçam condições de segurança e fluidez, observadas as características da via, do veículo, as condições meteorológicas e a movimentação de pedestres e ciclistas.', '["Retorno em locais determinados ou seguros.","Observância das condições da via e do ambiente."]'::jsonb, '["Retorno em local sem proibição e com segurança."]'::jsonb, 'O retorno é feito no local sinalizado.', '["Assertiva que permite retorno em qualquer ponto da via urbana erra."]'::jsonb, '[]'::jsonb, '["Art. 37"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-39'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O uso de luzes em veículo obedece a determinações como manter acesos os faróis, na luz baixa, à noite e, mesmo durante o dia, em túneis e sob chuva, neblina ou cerração; usar luz alta nas vias não iluminadas, exceto ao cruzar com outro veículo ou ao segui-lo; e não trocar de forma intermitente e por curto período a luz baixa e a alta, salvo para advertir ultrapassagem fora da área urbana.', '["Luz baixa à noite e em túneis, chuva e neblina.","Luz alta em vias não iluminadas, com exceções.","Regras sobre a troca intermitente."]'::jsonb, '["Luz baixa também de dia em túneis, chuva, neblina e cerração.","ATUALIZAÇÃO: regras sobre luzes diurnas em rodovias foram alteradas por lei posterior; confira o texto integral."]'::jsonb, 'Em túnel, mesmo de dia, mantém-se a luz baixa acesa.', '["Assertiva que dispensa os faróis acesos em túnel durante o dia erra."]'::jsonb, '[]'::jsonb, '["Art. 41"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-40'
