insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O condutor só pode fazer uso de buzina, em toque breve, para fazer as advertências necessárias a fim de evitar sinistros e, fora das áreas urbanas, quando for conveniente advertir outro condutor de que se tem o propósito de ultrapassá-lo.', '["Toque breve.","Para evitar sinistros.","Fora das áreas urbanas, para advertir ultrapassagem."]'::jsonb, '["Em área urbana, só para evitar sinistro."]'::jsonb, 'Na rodovia, o toque breve avisa que o condutor vai ultrapassar.', '["Assertiva que permite o uso livre da buzina nas áreas urbanas erra."]'::jsonb, '[]'::jsonb, '["Art. 40"]'::jsonb, 'under_review', 'claude'
