on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ao regular a velocidade, o condutor deve observar constantemente as condições físicas da via, do veículo e da carga, as condições meteorológicas e a intensidade do trânsito, obedecendo aos limites máximos de velocidade estabelecidos para a via, além de não obstruir a marcha normal dos demais veículos sem causa justificada, transitando a velocidade anormalmente reduzida.', '["Observar condições da via, do veículo, da carga e do clima.","Respeitar os limites máximos.","Não transitar em velocidade anormalmente reduzida sem causa justificada."]'::jsonb, '["Velocidade anormalmente reduzida sem causa também é irregular."]'::jsonb, 'Dirigir devagar demais e atrapalhar o fluxo viola a regra.', '["Assertiva que considera irregular apenas o excesso de velocidade, e não a velocidade anormalmente reduzida, erra."]'::jsonb, '[]'::jsonb, '["Art. 61"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-43'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ao aproximar-se de qualquer tipo de cruzamento, o condutor do veículo deve demonstrar prudência especial, transitando em velocidade moderada, de forma que possa deter seu veículo com segurança para dar passagem a pedestre e a veículos que tenham o direito de preferência.', '["Prudência especial nos cruzamentos.","Velocidade moderada.","Dar passagem a quem tem preferência."]'::jsonb, '["Vale para qualquer cruzamento."]'::jsonb, 'Ao chegar ao cruzamento, o condutor reduz para poder parar.', '["Assertiva que dispensa prudência especial em cruzamentos sinalizados erra."]'::jsonb, '[]'::jsonb, '["Art. 45"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-44'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É livre o movimento de conversão à direita diante de sinal vermelho do semáforo onde houver sinalização indicativa que permita essa conversão, observados os arts. 44, 45 e 70.', '["Conversão à direita no vermelho, só com sinalização permissiva."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior.","Exige SINALIZAÇÃO que permita; sem ela, é proibido."]'::jsonb, 'Há placa permitindo a conversão à direita no vermelho; o condutor pode converter com cautela.', '["Assertiva que permite a conversão à direita no vermelho em qualquer semáforo erra."]'::jsonb, '[]'::jsonb, '["Art. 44"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-44-a'
