insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Mesmo que a indicação luminosa do semáforo lhe seja favorável, nenhum condutor pode entrar em uma interseção se houver possibilidade de ser obrigado a imobilizar o veículo na área do cruzamento, obstruindo ou impedindo a passagem do trânsito transversal.', '["Proibido entrar na interseção sem espaço para sair.","Vale mesmo com sinal verde."]'::jsonb, '["Mesmo com semáforo favorável."]'::jsonb, 'O condutor não avança no verde se o trânsito à frente está parado.', '["Assertiva que autoriza entrar no cruzamento no verde, ainda que fique parado nele, erra."]'::jsonb, '[]'::jsonb, '["Art. 44"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-45'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Sempre que for necessária a imobilização temporária de um veículo no leito viário, em situação de emergência, deve ser providenciada a imediata sinalização de advertência, na forma estabelecida pelo Contran.', '["Sinalização imediata em imobilização de emergência.","Forma definida pelo Contran."]'::jsonb, '["Sinalização na forma do Contran, como o triângulo."]'::jsonb, 'Em pane na pista, o condutor coloca o triângulo de sinalização.', '["Assertiva que dispensa a sinalização na imobilização por emergência erra."]'::jsonb, '[]'::jsonb, '["Art. 47"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-46'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Quando proibido o estacionamento na via, a parada deve restringir-se ao tempo indispensável para embarque ou desembarque de passageiros, desde que não interrompa ou perturbe o fluxo de veículos ou a locomoção de pedestres. A operação de carga ou descarga é regulamentada pelo órgão com circunscrição sobre a via e é considerada estacionamento.', '["Parada só para embarque e desembarque.","Carga e descarga é considerada estacionamento."]'::jsonb, '["Carga ou descarga = ESTACIONAMENTO."]'::jsonb, 'Em local de estacionamento proibido, só se para para embarcar ou desembarcar.', '["Assertiva que considera carga e descarga como mera parada erra: é estacionamento."]'::jsonb, '[]'::jsonb, '["Art. 48"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-47'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nas paradas, operações de carga ou descarga e estacionamentos, o veículo deve ser posicionado no sentido do fluxo, paralelo ao bordo da pista de rolamento e junto à guia da calçada (meio-fio), admitidas as exceções sinalizadas. Nas vias providas de acostamento, os veículos parados, estacionados ou em operação de carga ou descarga devem estar fora da pista de rolamento.', '["Sentido do fluxo, paralelo e junto ao meio-fio.","Exceções sinalizadas.","Acostamento: fora da pista de rolamento."]'::jsonb, '["Posição: no sentido do fluxo e junto ao meio-fio."]'::jsonb, 'O veículo estaciona paralelo à guia, no sentido do fluxo.', '["Assertiva que permite estacionar em sentido contrário ao fluxo sem sinalização erra."]'::jsonb, '[]'::jsonb, '["Art. 47"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-48'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O condutor e os passageiros não devem abrir a porta do veículo, deixá-la aberta ou descer do veículo sem antes se certificarem de que isso não constitui perigo para eles e para outros usuários da via. O embarque e o desembarque devem ocorrer sempre do lado da calçada, exceto para o condutor.', '["Certificar-se antes de abrir a porta.","Embarque e desembarque do lado da calçada."]'::jsonb, '["Exceção do lado da calçada: o condutor."]'::jsonb, 'Antes de abrir a porta, confere-se se vem ciclista.', '["Assertiva que manda o passageiro desembarcar sempre pelo lado da pista erra."]'::jsonb, '[]'::jsonb, '["Art. 48"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-49'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O uso de faixas laterais de domínio e das áreas adjacentes às estradas e rodovias obedece às condições de segurança do trânsito estabelecidas pelo órgão ou entidade com circunscrição sobre a via.', '["Faixas de domínio e áreas adjacentes.","Condições definidas pelo órgão com circunscrição."]'::jsonb, '["Quem define é o órgão com circunscrição sobre a via."]'::jsonb, 'O uso da faixa de domínio depende de autorização e regras do órgão rodoviário.', '["Assertiva que libera o uso das faixas de domínio sem condições de segurança erra."]'::jsonb, '[]'::jsonb, '["Art. 21"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-50'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nas vias internas pertencentes a condomínios constituídos por unidades autônomas, a sinalização de regulamentação da via é implantada e mantida às expensas do condomínio, após aprovação dos projetos pelo órgão ou entidade com circunscrição sobre a via.', '["Sinalização às expensas do condomínio.","Aprovação dos projetos pelo órgão de trânsito."]'::jsonb, '["Condomínio paga, mas o órgão aprova o projeto."]'::jsonb, 'O condomínio instala as placas após aprovação do projeto pelo órgão.', '["Assertiva que isenta o condomínio da sinalização de suas vias erra."]'::jsonb, '[]'::jsonb, '["Art. 2º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-51'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os veículos de tração animal são conduzidos pela direita da pista, junto à guia da calçada (meio-fio) ou acostamento, sempre que não houver faixa especial a eles destinada, devendo seus condutores obedecer, no que couber, às normas de circulação do Código e às fixadas pelo órgão com circunscrição sobre a via.', '["Circulam pela direita, junto ao meio-fio ou acostamento.","Obedecem às normas de circulação, no que couber."]'::jsonb, '["Sem faixa especial, pela direita."]'::jsonb, 'A carroça trafega junto ao acostamento.', '["Assertiva que isenta veículos de tração animal das normas de circulação erra."]'::jsonb, '[]'::jsonb, '["Art. 53"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-52'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os animais isolados ou em grupos só podem circular nas vias quando conduzidos por um guia. Para facilitar os deslocamentos, os rebanhos devem ser divididos em grupos de tamanho moderado e separados uns dos outros por espaços suficientes para não obstruir o trânsito; e os animais que circularem pela pista de rolamento devem ser mantidos junto ao bordo da pista.', '["Animais só com guia.","Rebanhos divididos em grupos moderados.","Junto ao bordo da pista."]'::jsonb, '["Sem guia, o animal não pode circular na via."]'::jsonb, 'O vaqueiro conduz o gado dividido em grupos.', '["Assertiva que permite animais soltos na via erra."]'::jsonb, '[]'::jsonb, '["Art. 52"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-53'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os condutores de motocicletas, motonetas e ciclomotores só podem circular nas vias utilizando capacete de segurança com viseira ou óculos protetores, segurando o guidom com as duas mãos e usando vestuário de proteção de acordo com as especificações do Contran.', '["Capacete com viseira ou óculos.","Guidom com as duas mãos.","Vestuário de proteção conforme o Contran."]'::jsonb, '["Vestuário de proteção depende de regulamentação do Contran.","Três exigências cumulativas."]'::jsonb, 'O motociclista usa capacete e segura o guidom com as duas mãos.', '["Assertiva que dispensa o capacete em trajetos curtos erra."]'::jsonb, '[]'::jsonb, '["Art. 244"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-54'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os passageiros de motocicletas, motonetas e ciclomotores só podem ser transportados utilizando capacete de segurança, em carro lateral acoplado ao veículo ou em assento suplementar atrás do condutor, e usando vestuário de proteção de acordo com as especificações do Contran.', '["Capacete.","Carro lateral ou assento suplementar atrás do condutor.","Vestuário de proteção conforme o Contran."]'::jsonb, '["O passageiro também usa capacete."]'::jsonb, 'O passageiro da moto usa capacete e viaja no assento atrás do condutor.', '["Assertiva que dispensa o capacete do passageiro erra."]'::jsonb, '[]'::jsonb, '["Art. 54"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-55'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os ciclomotores são conduzidos pela direita da pista de rolamento, preferencialmente no centro da faixa mais à direita ou no bordo direito da pista, quando não houver acostamento ou faixa própria a eles destinada. É proibida a circulação de ciclomotores nas vias de trânsito rápido e sobre as calçadas das vias urbanas. Se a faixa da direita for de uso exclusivo de outro tipo de veículo, circulam pela faixa adjacente.', '["Circulação pela direita da pista.","Proibidos em vias de trânsito rápido.","Proibidos sobre calçadas urbanas."]'::jsonb, '["Vedados nas vias de trânsito rápido e nas calçadas."]'::jsonb, 'O ciclomotor não pode subir na calçada para fugir do congestionamento.', '["Assertiva que permite ciclomotores nas vias de trânsito rápido erra."]'::jsonb, '[]'::jsonb, '["Art. 60"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-57'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nas vias urbanas e nas rurais de pista dupla, a circulação de bicicletas deve ocorrer, quando não houver ciclovia, ciclofaixa ou acostamento, ou quando não for possível usá-los, nos bordos da pista de rolamento, no mesmo sentido da via, com preferência sobre os veículos automotores. A autoridade de trânsito pode autorizar a circulação de bicicletas em sentido contrário ao fluxo, se o trecho tiver ciclofaixa.', '["Bordos da pista, no mesmo sentido.","Preferência sobre veículos automotores.","Sentido contrário só com ciclofaixa e autorização."]'::jsonb, '["A bicicleta tem preferência sobre os automotores."]'::jsonb, 'Sem ciclovia, o ciclista trafega junto ao bordo da pista, no sentido da via.', '["Assertiva que dá preferência aos automotores sobre as bicicletas nos bordos da pista erra."]'::jsonb, '[]'::jsonb, '["Art. 59"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-58'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Desde que autorizado e devidamente sinalizado pelo órgão ou entidade com circunscrição sobre a via, é permitida a circulação de bicicletas nos passeios.', '["Circulação nos passeios só com autorização e sinalização."]'::jsonb, '["Sem autorização e sinalização, o passeio é do pedestre."]'::jsonb, 'A prefeitura sinaliza trecho de calçada compartilhada com bicicletas.', '["Assertiva que permite bicicleta em qualquer calçada erra."]'::jsonb, '[]'::jsonb, '["Art. 58"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-59'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As vias abertas à circulação classificam-se, de acordo com sua utilização, em vias urbanas, que podem ser de trânsito rápido, arteriais, coletoras ou locais, e vias rurais, que são as rodovias e as estradas.', '["Vias urbanas: trânsito rápido, arterial, coletora e local.","Vias rurais: rodovias e estradas."]'::jsonb, '["Quatro tipos de vias urbanas e dois de vias rurais."]'::jsonb, 'A avenida de ligação entre bairros é via arterial.', '["Assertiva que inclui a via rápida como via rural erra."]'::jsonb, '[]'::jsonb, '["Art. 61"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-60'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A velocidade máxima permitida para a via é indicada por sinalização. Onde não houver sinalização regulamentadora, é de oitenta quilômetros por hora nas vias de trânsito rápido, sessenta nas arteriais, quarenta nas coletoras e trinta nas locais. Nas vias rurais: em rodovias de pista dupla, 110 km/h para automóveis, camionetas, caminhonetes e motocicletas e 90 km/h para os demais veículos; em rodovias de pista simples, 100 km/h para automóveis, camionetas, caminhonetes e motocicletas e 90 km/h para os demais; e nas estradas, 60 km/h. O órgão com circunscrição pode regulamentar, por sinalização, velocidades superiores ou inferiores.', '["Urbanas: oitenta, sessenta, quarenta e trinta quilômetros por hora.","Rodovias de pista dupla: 110 km/h e 90 km/h.","Rodovias de pista simples: 100 km/h e 90 km/h.","Estradas: 60 km/h.","Regulamentação por sinalização prevalece."]'::jsonb, '["ATUALIZAÇÃO: os limites das rodovias foram alterados por lei posterior.","Esses valores valem onde NÃO houver sinalização regulamentadora."]'::jsonb, 'Na via local sem placa, o limite é de trinta quilômetros por hora.', '["Assertiva que fixa em sessenta quilômetros por hora o limite das vias locais sem sinalização erra: são trinta."]'::jsonb, '[]'::jsonb, '["Art. 218"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-61'
