insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As crianças com idade inferior a dez anos que não tenham atingido 1,45 m de altura devem ser transportadas nos bancos traseiros, em dispositivo de retenção adequado para cada idade, peso e altura, salvo exceções relacionadas a tipos específicos de veículos regulamentadas pelo Contran. O Contran disciplina o uso excepcional de dispositivos de retenção no banco dianteiro e suas especificações técnicas.', '["Menores de dez anos que não tenham atingido 1,45 m.","Banco traseiro.","Dispositivo de retenção adequado.","Exceções regulamentadas pelo Contran."]'::jsonb, '["ATUALIZAÇÃO: a regra de idade e altura veio de lei posterior.","O requisito é idade menor que dez anos E altura menor que 1,45 m."]'::jsonb, 'A criança de oito anos com 1,30 m viaja no banco traseiro com dispositivo de retenção.', '["Assertiva que dispensa o dispositivo de retenção para criança de sete anos erra."]'::jsonb, '[]'::jsonb, '["Art. 168"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-64'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É obrigatório o uso do cinto de segurança para condutor e passageiros em todas as vias do território nacional, salvo em situações regulamentadas pelo Contran.', '["Cinto obrigatório para condutor e passageiros.","Em todas as vias do país.","Exceções regulamentadas pelo Contran."]'::jsonb, '["Vale para condutor E passageiros, em TODAS as vias."]'::jsonb, 'O passageiro do banco traseiro também usa cinto.', '["Assertiva que dispensa o cinto dos passageiros do banco traseiro erra."]'::jsonb, '[]'::jsonb, '["Art. 167"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-65'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As provas ou competições desportivas, inclusive seus ensaios, em via aberta à circulação, só podem ser realizadas mediante prévia permissão da autoridade de trânsito e dependem de autorização expressa da confederação desportiva ou entidades estaduais filiadas, caução ou fiança para cobrir possíveis danos à via, contrato de seguro contra riscos e sinistros em favor de terceiros e prévio recolhimento dos custos operacionais.', '["Prévia permissão da autoridade de trânsito.","Autorização da confederação desportiva.","Caução ou fiança.","Seguro em favor de terceiros.","Recolhimento dos custos operacionais."]'::jsonb, '["Quatro condições além da permissão prévia."]'::jsonb, 'A corrida de rua exige permissão da autoridade, seguro e caução.', '["Assertiva que dispensa o seguro em favor de terceiros nas competições em via aberta erra."]'::jsonb, '[]'::jsonb, '["Art. 173"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-67'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As regras do capítulo sobre jornada de direção aplicam-se aos motoristas profissionais de transporte rodoviário coletivo de passageiros e de transporte rodoviário de cargas.', '["Aplicação aos motoristas de passageiros e de cargas."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído pela Lei do Motorista.","Alcança passageiros E cargas."]'::jsonb, 'O motorista de ônibus interestadual e o de caminhão submetem-se às regras de descanso.', '["Assertiva que exclui os motoristas de cargas das regras de descanso erra."]'::jsonb, '[]'::jsonb, '["Art. 67-C"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-67-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É vedado ao motorista profissional dirigir por mais de cinco horas e meia ininterruptas veículos de transporte rodoviário coletivo de passageiros ou de cargas. Observam-se 30 minutos de descanso dentro de cada 6 horas na condução de veículo de carga, e 30 minutos a cada 4 horas no transporte rodoviário de passageiros, facultado o fracionamento. O condutor deve observar, em 24 horas, no mínimo 11 horas de descanso, com 8 horas ininterruptas no primeiro período. Tempo de direção é apenas o período efetivamente ao volante. O condutor só inicia a viagem após cumprir integralmente o intervalo de descanso. Em situações excepcionais justificadas, o tempo pode ser elevado.', '["Máximo de cinco horas e meia ininterruptas ao volante.","Descanso de 30 minutos: a cada 6 horas (carga) e a cada 4 horas (passageiros).","Mínimo de 11 horas de descanso em 24 horas, sendo 8 ininterruptas.","Situações excepcionais justificadas."]'::jsonb, '["ATUALIZAÇÃO: a Lei do Motorista alterou o regime de jornada e descanso; confira o texto vigente.","Cinco horas e meia ininterruptas; descanso diário de 11 horas."]'::jsonb, 'O caminhoneiro para por 30 minutos antes de completar 6 horas de condução.', '["Assertiva que permite dirigir por 8 horas ininterruptas erra: o máximo é cinco horas e meia."]'::jsonb, '[]'::jsonb, '["Art. 67-E"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-67-c'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O motorista profissional é responsável por controlar e registrar o tempo de condução, com vistas à estrita observância do art. 67-C. A inobservância dos períodos de descanso o sujeita às penalidades do Código, salvo a situação excepcional dos transportadores de cargas. O tempo é controlado por registrador instantâneo inalterável de velocidade e tempo, diário de bordo, papeleta, ficha de trabalho externo ou meios eletrônicos, conforme norma do Contran. O equipamento funciona de forma independente do condutor, que é responsável pela guarda, preservação e exatidão das informações.', '["Controle e registro pelo motorista.","Penalidades pela inobservância do descanso.","Registro por tacógrafo, diário de bordo ou meios eletrônicos.","Condutor responde pela guarda e exatidão dos dados."]'::jsonb, '["ATUALIZAÇÃO: a Lei do Motorista criou exceção de penalidades para situações excepcionais no transporte de cargas.","O condutor é responsável pelo equipamento registrador."]'::jsonb, 'O motorista guarda o disco do tacógrafo e responde por sua exatidão.', '["Assertiva que transfere ao embarcador a responsabilidade pela exatidão do registrador erra."]'::jsonb, '[]'::jsonb, '["Art. 67-C"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-67-e'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É assegurada ao pedestre a utilização dos passeios ou passagens apropriadas das vias urbanas e dos acostamentos das vias rurais para circulação, podendo a autoridade permitir a utilização de parte da calçada para outros fins, se não prejudicar o fluxo de pedestres. O ciclista desmontado empurrando a bicicleta equipara-se ao pedestre. Na falta de passeios, o pedestre circula na pista pelos bordos, em fila única, com prioridade sobre os veículos, exceto em locais proibidos.', '["Passeios, passagens e acostamentos para pedestres.","Ciclista desmontado equipara-se a pedestre.","Sem passeio: bordos da pista, em fila única, com prioridade."]'::jsonb, '["Ciclista desmontado = pedestre."]'::jsonb, 'O ciclista que empurra a bicicleta pela calçada tem direitos de pedestre.', '["Assertiva que trata o ciclista desmontado como condutor de veículo erra."]'::jsonb, '[]'::jsonb, '["Art. 69"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-68'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Para cruzar a pista de rolamento, o pedestre toma precauções de segurança, considerando a visibilidade, a distância e a velocidade dos veículos, usando sempre as faixas ou passagens destinadas a ele, quando existirem a até cinquenta metros. Onde não houver faixa, cruza em sentido perpendicular ao eixo da via. Em passagem sinalizada, obedece ao foco de pedestres ou aguarda que o semáforo ou o agente interrompa o fluxo. Nas interseções sem faixa, atravessa na continuação da calçada, sem obstruir o trânsito e sem demorar-se ou parar na pista.', '["Usar faixas existentes até cinquenta metros.","Cruzamento perpendicular quando não há faixa.","Obedecer ao foco de pedestres.","Não demorar ou parar na pista."]'::jsonb, '["Distância de até cinquenta metros para a obrigação de usar a faixa."]'::jsonb, 'Se há faixa a trinta metros, o pedestre deve usá-la para atravessar.', '["Assertiva que fixa em cem metros a distância para o uso obrigatório da faixa erra: são até cinquenta metros."]'::jsonb, '[]'::jsonb, '["Art. 70"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-69'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os pedestres que atravessam a via sobre as faixas delimitadas para esse fim têm prioridade de passagem, exceto nos locais com sinalização semafórica, onde devem ser respeitadas as disposições do Código. Onde houver semáforo de controle de passagem, é dada preferência aos pedestres que não tenham concluído a travessia, mesmo que o semáforo libere a passagem dos veículos.', '["Prioridade do pedestre sobre a faixa.","Exceção nos locais com semáforo.","Preferência ao pedestre que não concluiu a travessia."]'::jsonb, '["Mesmo com a mudança do semáforo, quem ainda atravessa tem preferência."]'::jsonb, 'O veículo espera o pedestre terminar de atravessar, ainda que o sinal já esteja verde.', '["Assertiva que dá preferência ao veículo assim que o semáforo abre erra."]'::jsonb, '[]'::jsonb, '["Art. 214"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-70'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O órgão ou entidade com circunscrição sobre a via mantém, obrigatoriamente, as faixas e passagens de pedestres em boas condições de visibilidade, higiene, segurança e sinalização.', '["Manutenção obrigatória das faixas de pedestres."]'::jsonb, '["Dever do órgão com circunscrição."]'::jsonb, 'A prefeitura repinta as faixas apagadas.', '["Assertiva que transfere ao pedestre a manutenção da faixa erra."]'::jsonb, '[]'::jsonb, '["Art. 85"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-71'
