insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Todo cidadão ou entidade civil tem o direito de solicitar, por escrito, aos órgãos do Sistema Nacional de Trânsito, sinalização, fiscalização e implantação de equipamentos de segurança, bem como sugerir alterações em normas, legislação e outros assuntos pertinentes ao Código.', '["Solicitação por escrito.","Sinalização, fiscalização e equipamentos.","Sugestão de alterações normativas."]'::jsonb, '["Direito de qualquer cidadão ou entidade civil."]'::jsonb, 'A associação de moradores pede por escrito a instalação de lombada.', '["Assertiva que restringe o direito de solicitar a entidades públicas erra."]'::jsonb, '[]'::jsonb, '["Art. 73"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-72'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os órgãos do Sistema Nacional de Trânsito têm o dever de analisar as solicitações e responder, por escrito, dentro de prazos mínimos, sobre a possibilidade ou não de atendimento, justificando a análise e, se pertinente, informando quando o evento ocorrerá. As campanhas de trânsito devem esclarecer as atribuições dos órgãos e como proceder a tais solicitações.', '["Dever de analisar e responder por escrito.","Justificar a análise.","Campanhas esclarecem como solicitar."]'::jsonb, '["Resposta por escrito e justificada."]'::jsonb, 'O órgão responde por escrito que a lombada será instalada ou justifica por que não.', '["Assertiva que permite ao órgão ignorar as solicitações erra."]'::jsonb, '[]'::jsonb, '["Art. 72"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-73'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A educação para o trânsito é direito de todos e dever prioritário dos componentes do Sistema Nacional de Trânsito. É obrigatória a existência de coordenação educacional em cada órgão ou entidade do Sistema, e os órgãos executivos devem promover o funcionamento de Escolas Públicas de Trânsito, nos moldes do Contran.', '["Direito de todos.","Coordenação educacional obrigatória.","Escolas Públicas de Trânsito."]'::jsonb, '["Dever PRIORITÁRIO do sistema."]'::jsonb, 'O Detran mantém a Escola Pública de Trânsito.', '["Assertiva que torna facultativa a coordenação educacional nos órgãos do sistema erra."]'::jsonb, '[]'::jsonb, '["Art. 75"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-74'
