insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Contran especifica o conteúdo e o padrão de apresentação das mensagens educativas, bem como os procedimentos de sua veiculação, em conformidade com as diretrizes das campanhas educativas de trânsito do art. 75.', '["Contran define conteúdo, padrão e procedimentos."]'::jsonb, '["Competência do Contran."]'::jsonb, 'O Contran estabelece o formato da mensagem nas propagandas.', '["Assertiva que atribui a cada anunciante a definição do conteúdo da mensagem erra."]'::jsonb, '[]'::jsonb, '["Art. 75"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-77-d'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A veiculação de publicidade em desacordo com as condições dos arts. 77-A a 77-D é infração punível com advertência por escrito, suspensão de qualquer outra propaganda do produto nos veículos de divulgação por até sessenta dias e multa de R$ 1.627,00 a R$ 8.135,00, cobrada do dobro até o quíntuplo em caso de reincidência. As sanções são aplicadas isolada ou cumulativamente, e qualquer infração acarreta a imediata suspensão da veiculação da peça até o cumprimento das exigências.', '["Advertência por escrito.","Suspensão da propaganda por até sessenta dias.","Multa de R$ 1.627,00 a R$ 8.135,00.","Sanções isoladas ou cumulativas."]'::jsonb, '["Multa do dobro ao quíntuplo na reincidência.","Valores em reais fixados no texto legal; confira eventual atualização."]'::jsonb, 'A emissora exibe propaganda sem mensagem e a peça é suspensa até a regularização.', '["Assertiva que impede a cumulação das sanções erra: podem ser aplicadas cumulativamente."]'::jsonb, '[]'::jsonb, '["Art. 77-B"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-77-e'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os Ministérios da Saúde, da Educação, do Trabalho e Emprego, dos Transportes e da Justiça e Segurança Pública, por intermédio do Contran, desenvolvem e implementam programas destinados à prevenção de sinistros. É repassado mensalmente ao Coordenador do Sistema Nacional de Trânsito o montante equivalente a até 5% do total dos valores arrecadados destinados à Seguridade Social dos prêmios do seguro obrigatório, para aplicação nos programas e na divulgação.', '["Programas de prevenção de sinistros.","Repasse mensal de até 5% da arrecadação do seguro obrigatório."]'::jsonb, '["ATUALIZAÇÃO: a redação do parágrafo único mudou conforme a legislação do seguro obrigatório; confira o texto vigente.","Repasse de até 5%."]'::jsonb, 'Parte da arrecadação do seguro financia campanhas de prevenção.', '["Assertiva que fixa em 10% o repasse erra: são até 5%."]'::jsonb, '[]'::jsonb, '["Art. 75"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-78'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os órgãos e entidades executivos de trânsito podem firmar convênio com os órgãos de educação da União, dos Estados, do Distrito Federal e dos Municípios, objetivando o cumprimento das obrigações do capítulo sobre educação para o trânsito.', '["Convênio com órgãos de educação."]'::jsonb, '["Faculdade, por meio de convênio."]'::jsonb, 'O Detran firma convênio com a secretaria de educação.', '["Assertiva que torna obrigatório o convênio com os órgãos de educação erra."]'::jsonb, '[]'::jsonb, '["Art. 76"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-79'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Sempre que necessário, é colocada ao longo da via a sinalização prevista no Código e em legislação complementar, destinada a condutores e pedestres, vedada a utilização de qualquer outra. A sinalização deve ficar em posição e condições que a tornem perfeitamente visível e legível, de dia e de noite, em distância compatível com a segurança, conforme normas do Contran. O órgão máximo executivo de trânsito da União pode autorizar, em caráter experimental e por período prefixado, sinalização e equipamentos não previstos no Código.', '["Só a sinalização prevista em lei.","Visível e legível de dia e de noite.","Uso experimental autorizado pelo órgão máximo executivo da União."]'::jsonb, '["Vedada outra sinalização não prevista."]'::jsonb, 'Placa não prevista só é usada em caráter experimental autorizado.', '["Assertiva que permite qualquer sinalização à escolha do município erra."]'::jsonb, '[]'::jsonb, '["Art. 90"]'::jsonb, 'under_review', 'claude'
