insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os sinais de trânsito classificam-se em verticais, horizontais, dispositivos de sinalização auxiliar, luminosos, sonoros e gestos do agente de trânsito e do condutor.', '["Seis categorias de sinais."]'::jsonb, '["Seis categorias."]'::jsonb, 'Placa, faixa pintada no chão e semáforo são sinais de categorias diferentes.', '["Assertiva que exclui os gestos do agente da classificação dos sinais erra."]'::jsonb, '[]'::jsonb, '["Art. 89"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-87'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nenhuma via pavimentada pode ser entregue após sua construção, ou reaberta ao trânsito após obras ou manutenção, enquanto não estiver devidamente sinalizada, vertical e horizontalmente, de forma a garantir condições adequadas de segurança. Nas vias ou trechos em obras deve ser afixada sinalização específica e adequada.', '["Sinalização vertical e horizontal antes da entrega.","Sinalização específica em obras."]'::jsonb, '["Sem sinalização, a via não pode ser aberta."]'::jsonb, 'A via recapeada só é liberada após a pintura das faixas.', '["Assertiva que permite abrir a via ao trânsito antes de sinalizá-la erra."]'::jsonb, '[]'::jsonb, '["Art. 90"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-88'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A sinalização tem a seguinte ordem de prevalência: as ordens do agente de trânsito prevalecem sobre as normas de circulação e outros sinais; as indicações do semáforo prevalecem sobre os demais sinais; e as indicações dos sinais prevalecem sobre as demais normas de trânsito.', '["Agente de trânsito.","Semáforo.","Sinais.","Normas de circulação."]'::jsonb, '["Ordem: agente, semáforo, sinais, normas."]'::jsonb, 'O agente manda avançar no sinal vermelho; prevalece a ordem do agente.', '["Assertiva que coloca o semáforo acima das ordens do agente erra."]'::jsonb, '[]'::jsonb, '["Art. 87"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-89'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Não são aplicadas as sanções do Código por inobservância à sinalização quando esta for insuficiente ou incorreta. O órgão ou entidade de trânsito com circunscrição sobre a via é responsável pela implantação da sinalização, respondendo pela falta, insuficiência ou incorreta colocação. O Contran edita normas complementares sobre interpretação, colocação e uso da sinalização.', '["Sinalização insuficiente ou incorreta afasta a sanção.","Responsabilidade do órgão pela sinalização."]'::jsonb, '["Sinalização deficiente = sem sanção ao condutor."]'::jsonb, 'A multa por placa ausente ou incorreta não pode ser aplicada.', '["Assertiva que mantém a sanção mesmo com sinalização insuficiente erra."]'::jsonb, '[]'::jsonb, '["Art. 80"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-90'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Contran estabelece as normas e regulamentos a serem adotados em todo o território nacional na implementação das soluções da Engenharia de Tráfego, assim como os padrões a serem praticados por todos os órgãos e entidades do Sistema Nacional de Trânsito.', '["Normas nacionais de engenharia de tráfego.","Padrões para todos os órgãos."]'::jsonb, '["Padronização nacional pelo Contran."]'::jsonb, 'A mesma regra de projeto de sinalização vale em todo o país.', '["Assertiva que deixa a engenharia de tráfego sem padronização nacional erra."]'::jsonb, '[]'::jsonb, '["Art. 12"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-91'
