insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nenhum projeto de edificação que possa transformar-se em polo atrativo de trânsito pode ser aprovado sem prévia anuência do órgão ou entidade com circunscrição sobre a via e sem que do projeto conste área para estacionamento e indicação das vias de acesso adequadas.', '["Anuência prévia do órgão de trânsito.","Área de estacionamento e vias de acesso."]'::jsonb, '["Polo atrativo de trânsito exige anuência prévia."]'::jsonb, 'Um shopping só é aprovado com estacionamento e acessos adequados.', '["Assertiva que dispensa área de estacionamento no projeto de polos atrativos erra."]'::jsonb, '[]'::jsonb, '["Art. 95"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-93'
