insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Qualquer obstáculo à livre circulação e à segurança de veículos e pedestres, na via ou na calçada, que não possa ser retirado, deve ser devida e imediatamente sinalizado. É proibida a utilização de ondulações transversais e de sonorizadores como redutores de velocidade, salvo casos especiais definidos pelo órgão competente, nos padrões do Contran.', '["Obstáculo não removível deve ser sinalizado.","Ondulações e sonorizadores só em casos especiais."]'::jsonb, '["Lombada só nos casos e padrões definidos pelo Contran."]'::jsonb, 'A lombada segue o padrão definido pelo Contran.', '["Assertiva que permite instalar lombadas sem padrão do Contran erra."]'::jsonb, '[]'::jsonb, '["Art. 91"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-94'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nenhuma obra ou evento que possa perturbar ou interromper a livre circulação de veículos e pedestres, ou colocar em risco sua segurança, pode ser iniciada sem permissão prévia do órgão de trânsito com circunscrição sobre a via. A obrigação de sinalizar é do responsável pela execução ou manutenção da obra ou do evento. Salvo emergência, a autoridade avisa a comunidade pelos meios de comunicação com quarenta e oito horas de antecedência de qualquer interdição da via, indicando caminhos alternativos.', '["Permissão prévia para obras e eventos.","Sinalização a cargo do responsável.","Aviso à comunidade com quarenta e oito horas de antecedência."]'::jsonb, '["Aviso com quarenta e oito horas de antecedência, salvo emergência."]'::jsonb, 'A interdição programada é anunciada com dois dias de antecedência.', '["Assertiva que dispensa o aviso prévio nas interdições programadas erra."]'::jsonb, '[]'::jsonb, '["Art. 93"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-95'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os veículos classificam-se quanto à tração em automotor, de propulsão humana, de tração animal e reboque ou semirreboque; e quanto à espécie em veículos de passageiros (bicicleta, ciclomotor, motoneta, motocicleta, triciclo, quadriciclo, automóvel, micro-ônibus, ônibus, bonde, reboque, charrete), de carga, mistos, de competição e de tração, entre outras categorias, além de quanto à categoria.', '["Classificação por tração.","Classificação por espécie: passageiros, carga, misto, competição e tração.","Há também classificação por categoria."]'::jsonb, '["Consulte o texto integral para a lista completa por espécie e categoria."]'::jsonb, 'A motocicleta é veículo automotor da espécie passageiros.', '["Assertiva que inclui a carroça entre os veículos de passageiros erra: é de carga."]'::jsonb, '[]'::jsonb, '["Anexo I"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-96'
