insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As repartições aduaneiras e os órgãos de controle de fronteira comunicam diretamente ao Renavam a entrada e a saída temporária ou definitiva de veículos. Os veículos licenciados no exterior não podem sair do território nacional sem o prévio pagamento ou depósito dos valores das infrações de trânsito e do ressarcimento de danos que tiverem causado ao patrimônio público ou de particulares. Os que saírem sem esse cumprimento e forem flagrados tentando ingressar ou em circulação no território nacional são retidos até a regularização.', '["Comunicação ao Renavam.","Saída condicionada ao pagamento das infrações e danos.","Retenção em caso de nova entrada sem regularização."]'::jsonb, '["Saída do veículo estrangeiro só após pagar ou depositar infrações e danos."]'::jsonb, 'O turista paga as multas antes de deixar o país com o carro.', '["Assertiva que permite a saída do veículo estrangeiro com multas pendentes erra."]'::jsonb, '[]'::jsonb, '["Art. 118"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-119'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Todo veículo automotor, articulado, reboque ou semirreboque deve ser registrado perante o órgão executivo de trânsito do Estado ou do Distrito Federal, no Município de domicílio ou residência de seu proprietário. Veículos oficiais da administração direta de qualquer poder são registrados com indicação expressa, por pintura nas portas, do nome, sigla ou logotipo do órgão, excetuados os de representação e os do art. 116. A regra não se aplica ao veículo de uso bélico.', '["Registro no órgão estadual ou distrital.","Município de domicílio do proprietário.","Identificação pintada nos veículos oficiais."]'::jsonb, '["Veículos oficiais: identificação pintada nas portas."]'::jsonb, 'O proprietário registra o carro no Detran do seu estado de domicílio.', '["Assertiva que manda registrar o veículo no órgão federal erra: é o órgão estadual ou distrital."]'::jsonb, '[]'::jsonb, '["Art. 121"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-120'
