insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Para a expedição do CRV, o órgão executivo de trânsito consulta o cadastro do Renavam e exige do proprietário a nota fiscal fornecida pelo fabricante ou revendedor, ou documento equivalente expedido por autoridade competente, e, em veículo importado por membro de missões diplomáticas ou organismos internacionais, o documento do Ministério das Relações Exteriores.', '["Consulta ao Renavam.","Nota fiscal ou documento equivalente.","Documento do Itamaraty para diplomatas."]'::jsonb, '["Primeiro registro exige nota fiscal."]'::jsonb, 'A concessionária entrega a nota fiscal para o primeiro registro.', '["Assertiva que dispensa a nota fiscal para o primeiro registro erra."]'::jsonb, '[]'::jsonb, '["Art. 121"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-122'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É obrigatória a expedição de novo CRV quando for transferida a propriedade, o proprietário mudar o Município de domicílio ou residência, for alterada qualquer característica do veículo ou houver mudança de categoria. Na transferência de propriedade, o prazo para as providências é de trinta dias; nos demais casos, as providências são imediatas. A mudança de endereço no mesmo Município é comunicada em trinta dias. A transferência pode ser feita integralmente por meio eletrônico, com assinaturas eletrônicas qualificadas ou avançadas, nos termos da regulamentação.', '["Quatro hipóteses de novo CRV.","Trinta dias na transferência de propriedade.","Trinta dias para comunicar mudança de endereço no mesmo Município.","Transferência eletrônica."]'::jsonb, '["Transferência de propriedade: TRINTA dias.","ATUALIZAÇÃO: transferência totalmente eletrônica prevista por lei posterior."]'::jsonb, 'O comprador tem trinta dias para transferir o veículo para o seu nome.', '["Assertiva que fixa em sessenta dias o prazo do comprador para a transferência erra: são trinta dias."]'::jsonb, '[]'::jsonb, '["Art. 134"]'::jsonb, 'under_review', 'claude'
