insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As informações sobre o chassi, o monobloco, os agregados e as características originais do veículo devem ser prestadas ao Renavam pelo fabricante ou montadora antes da comercialização, no caso de veículo nacional; pelo órgão alfandegário, no caso de veículo importado por pessoa física; e pelo importador, no caso de importado por pessoa jurídica. As informações são repassadas ao órgão responsável pelo registro, que comunica ao Renavam quando o veículo for registrado.', '["Fabricante: veículo nacional.","Órgão alfandegário: importado por pessoa física.","Importador: importado por pessoa jurídica."]'::jsonb, '["Quem informa depende da origem e do importador."]'::jsonb, 'A montadora cadastra o veículo no Renavam antes de vendê-lo.', '["Assertiva que atribui ao proprietário a prestação das informações originais ao Renavam erra."]'::jsonb, '[]'::jsonb, '["Art. 103"]'::jsonb, 'under_review', 'claude'
