insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O registro de contratos de garantias de alienação fiduciária em operações financeiras, consórcio, arrendamento mercantil, reserva de domínio ou penhor é realizado nos órgãos executivos de trânsito dos Estados e do Distrito Federal, observados o Código Civil e a Lei Geral de Proteção de Dados Pessoais. O registro é executado por empresas registradoras especializadas, credenciadas pelos órgãos executivos de trânsito.', '["Registro de garantias no órgão estadual ou distrital.","Empresas registradoras credenciadas."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior.","Observa a proteção de dados pessoais."]'::jsonb, 'O gravame do financiamento é registrado por empresa credenciada.', '["Assertiva que atribui ao banco o registro direto do gravame no Renavam erra."]'::jsonb, '[]'::jsonb, '["Art. 121"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-129-b'
