select u.id, u.content_sha256, 'A autorização do veículo escolar deve ser afixada na parte interna do veículo, em local visível, com inscrição da lotação permitida, sendo vedada a condução de escolares em número superior à capacidade estabelecida pelo fabricante.', '["Autorização afixada em local visível.","Lotação inscrita.","Vedado exceder a capacidade."]'::jsonb, '["Lotação do fabricante é o limite."]'::jsonb, 'A van escolar exibe a autorização e a lotação dentro do veículo.', '["Assertiva que permite exceder a capacidade do fabricante com crianças pequenas erra."]'::jsonb, '[]'::jsonb, '["Art. 136"]'::jsonb, 'under_review', 'claude'
