select u.id, u.content_sha256, 'A habilitação para conduzir veículo automotor é apurada por meio de exames realizados no órgão ou entidade executivos do Estado ou do Distrito Federal do domicílio ou residência do candidato, ou na sede estadual ou distrital do próprio órgão. O candidato deve ser penalmente imputável, saber ler e escrever e possuir Carteira de Identidade ou equivalente. As informações do candidato são cadastradas no Renach.', '["Exames no órgão estadual ou distrital.","Imputável, alfabetizado e com identidade.","Cadastro no Renach."]'::jsonb, '["Requisitos: imputabilidade penal, saber ler e escrever, identidade."]'::jsonb, 'O candidato maior de dezoito anos, alfabetizado e com identidade pode se habilitar.', '["Assertiva que dispensa saber ler e escrever para a habilitação erra."]'::jsonb, '[{"termo":"Renach","significado":"Registro Nacional de Carteiras de Habilitação."}]'::jsonb, '["Art. 141"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-140'
