insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O processo de habilitação e as normas relativas à aprendizagem para conduzir veículos automotores e à autorização para conduzir ciclomotores são regulamentados pelo Contran. A autorização para conduzir veículos de propulsão humana e de tração animal fica a cargo dos Municípios.', '["Regulamentação pelo Contran.","Municípios autorizam propulsão humana e tração animal."]'::jsonb, '["Municípios, não os Detrans, autorizam condutores de tração animal."]'::jsonb, 'O Contran regula as aulas e o processo de habilitação.', '["Assertiva que atribui ao Detran a autorização de condutores de tração animal erra."]'::jsonb, '[]'::jsonb, '["Art. 140"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-141'
