on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os candidatos podem habilitar-se nas categorias A a E. A categoria A é de veículo motorizado de duas ou três rodas; B, de veículo cujo peso bruto total não exceda 3.500 kg e a lotação oito lugares, excluído o motorista; C, de veículos da B e de carga com peso bruto total acima de 3.500 kg; D, de veículos das B e C e de transporte de passageiros com lotação acima de oito lugares; E, de combinações em que a unidade acoplada tenha 6.000 kg ou mais de peso bruto total ou lotação acima de oito lugares. Para a categoria C exige-se um ano de categoria B e não mais de uma infração gravíssima nos últimos doze meses. A categoria B também autoriza motor-casa até 6.000 kg e veículos elétricos ou híbridos até 4.250 kg.', '["Categorias A a E em gradação.","Limites de 3.500 kg e de oito lugares.","C exige um ano de B.","B autoriza motor-casa e veículos elétricos ou híbridos nos limites legais."]'::jsonb, '["ATUALIZAÇÃO: limites da categoria C e extensões da B foram alterados por leis recentes.","Categoria B: até 3.500 kg e oito lugares."]'::jsonb, 'Quem tem categoria B há um ano e sem reincidência grave pode pedir a categoria C.', '["Assertiva que fixa em 3.000 kg o limite de peso da categoria B erra: são 3.500 kg."]'::jsonb, '[]'::jsonb, '["Art. 145"]'::jsonb, 'under_review', 'claude'
