insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O trator de roda, o trator de esteira, o trator misto ou o equipamento automotor destinado à movimentação de cargas ou execução de trabalho agrícola, de terraplenagem, construção ou pavimentação só podem ser conduzidos na via pública por condutor habilitado nas categorias C, D ou E. O trator de roda e os equipamentos para trabalhos agrícolas podem também ser conduzidos por condutor da categoria B.', '["Categorias C, D ou E.","Exceção: trator de roda e equipamentos agrícolas com categoria B."]'::jsonb, '["Exceção só para tratores de roda e equipamentos agrícolas."]'::jsonb, 'O agricultor com categoria B conduz trator de roda na via.', '["Assertiva que permite a categoria B para conduzir trator de esteira na via erra."]'::jsonb, '[]'::jsonb, '["Art. 143"]'::jsonb, 'under_review', 'claude'
