insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Para habilitar-se nas categorias D e E ou para conduzir veículo de transporte coletivo de passageiros, de escolares, de emergência ou de produto perigoso, o candidato deve ser maior de vinte e um anos; estar habilitado há, no mínimo, dois anos na categoria B ou um ano na categoria C, para a categoria D, e há um ano na categoria C, para a categoria E; não ter cometido mais de uma infração gravíssima nos últimos doze meses; e ser aprovado em curso especializado e em treinamento de prática veicular em situação de risco, nos termos do Contran.', '["Maior de vinte e um anos.","Tempo mínimo de habilitação prévia.","No máximo uma infração gravíssima em doze meses.","Curso especializado e treinamento em situação de risco."]'::jsonb, '["D: dois anos na B ou um ano na C; E: um ano na C.","ATUALIZAÇÃO: requisitos ajustados por leis recentes."]'::jsonb, 'Quem tem categoria B há dois anos pode buscar a categoria D, atendidos os demais requisitos.', '["Assertiva que fixa em dezoito anos a idade mínima para a categoria D erra: são mais de vinte e um anos."]'::jsonb, '[]'::jsonb, '["Art. 143"]'::jsonb, 'under_review', 'claude'
