insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Além do art. 145, para conduzir ambulâncias o candidato deve comprovar treinamento especializado e reciclagem em cursos específicos a cada cinco anos, nos termos da normatização do Contran.', '["Treinamento especializado.","Reciclagem a cada cinco anos."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior.","Reciclagem a cada cinco anos."]'::jsonb, 'O motorista de ambulância refaz o curso a cada cinco anos.', '["Assertiva que fixa em dois anos a reciclagem do condutor de ambulância erra: são cinco anos."]'::jsonb, '[]'::jsonb, '["Art. 145"]'::jsonb, 'under_review', 'claude'
