insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A Carteira Nacional de Habilitação pode ser emitida em meio físico ou digital, a critério do candidato ou do condutor; deve conter fotografia, nome, número do CPF e demais requisitos do Contran; e tem fé pública e equivale a documento de identidade no território nacional. É obrigatório o porte da Permissão para Dirigir ou da CNH quando o condutor estiver à direção, dispensado se for possível verificar a habilitação no sistema. Só tem validade quando apresentada em original. A renovação ou nova via só é feita após quitação dos débitos do prontuário, e a validade da CNH está condicionada à vigência do exame de aptidão física e mental. Os órgãos enviam aviso de vencimento com trinta dias de antecedência.', '["CNH física ou digital, com fé pública e valor de identidade.","Porte obrigatório, com dispensa se houver consulta ao sistema.","Validade só em original.","Renovação após quitação de débitos.","Aviso de vencimento com trinta dias de antecedência."]'::jsonb, '["ATUALIZAÇÃO: CNH digital e dispensa do porte vieram de leis posteriores.","Validade da CNH vinculada ao exame de aptidão física e mental."]'::jsonb, 'O condutor apresenta a CNH digital ou o agente consulta o sistema.', '["Assertiva que torna válida a cópia autenticada da CNH erra: só vale o original."]'::jsonb, '[]'::jsonb, '["Art. 147"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-159'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O condutor condenado por delito de trânsito deve ser submetido a novos exames para voltar a dirigir, conforme as normas do Contran, independentemente do reconhecimento da prescrição em face da pena concretizada na sentença. Em caso de sinistro grave, o condutor envolvido pode ser submetido aos exames, a juízo da autoridade executiva estadual de trânsito, assegurada ampla defesa, e esta pode apreender o documento de habilitação até a aprovação nos exames.', '["Novos exames após condenação por delito de trânsito.","Independe da prescrição.","Sinistro grave: exames a juízo da autoridade, com ampla defesa.","Apreensão do documento até a aprovação."]'::jsonb, '["Exames exigidos mesmo com prescrição."]'::jsonb, 'O condutor condenado por homicídio culposo no trânsito refaz os exames para voltar a dirigir.', '["Assertiva que dispensa os exames se houver prescrição da pena erra."]'::jsonb, '[]'::jsonb, '["Art. 147"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-160'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Constitui infração de trânsito a inobservância de qualquer preceito do Código ou da legislação complementar, e o infrator sujeita-se às penalidades e medidas administrativas indicadas em cada artigo do capítulo e às punições do capítulo dos crimes de trânsito.', '["Infração = inobservância do Código ou da legislação complementar.","Penalidades e medidas administrativas de cada artigo."]'::jsonb, '["Infração administrativa e crime são esferas distintas."]'::jsonb, 'Quem descumpre uma regra do Código comete infração de trânsito.', '["Assertiva que restringe as infrações às hipóteses do capítulo específico erra."]'::jsonb, '[]'::jsonb, '["Art. 256"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-161'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Dirigir veículo sem possuir CNH, Permissão para Dirigir ou Autorização para Conduzir Ciclomotor é infração gravíssima, com multa (três vezes) e retenção do veículo até a apresentação de condutor habilitado. Dirigir com habilitação cassada ou com suspensão do direito de dirigir também é gravíssima, com multa (três vezes), recolhimento do documento e retenção do veículo. Dirigir com habilitação de categoria diferente é gravíssima, com multa (duas vezes) e retenção. Também é gravíssima dirigir com CNH vencida há mais de trinta dias, sem lentes corretoras, aparelho auxiliar de audição ou adaptações impostas, ou sem os cursos especializados obrigatórios, com multa e retenção do veículo.', '["Sem habilitação: gravíssima, multa três vezes.","Habilitação cassada ou suspensa: gravíssima, multa três vezes.","Categoria diferente: gravíssima, multa duas vezes.","CNH vencida há mais de trinta dias: gravíssima.","Sem lentes corretoras ou adaptações impostas: gravíssima."]'::jsonb, '["Sem habilitação e cassada/suspensa: multa TRÊS vezes.","Categoria diferente: multa DUAS vezes.","ATUALIZAÇÃO: a CNH vencida há mais de trinta dias passou a ser gravíssima por lei posterior."]'::jsonb, 'Quem dirige sem CNH sofre multa de três vezes e retenção do veículo.', '["Assertiva que classifica como média a direção com CNH de categoria diferente erra: é gravíssima."]'::jsonb, '[]'::jsonb, '["Art. 163"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-162'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Entregar a direção do veículo a pessoa nas condições previstas no artigo anterior é infração com as mesmas características e penalidades do artigo 162, com a medida administrativa de retenção do veículo até a apresentação de condutor habilitado.', '["Mesmas infração e penalidades do art. 162.","Retenção do veículo."]'::jsonb, '["Quem entrega a direção sofre as mesmas penalidades."]'::jsonb, 'O proprietário que entrega o carro a quem não tem CNH é autuado.', '["Assertiva que isenta o proprietário que entrega a direção a quem não é habilitado erra."]'::jsonb, '[]'::jsonb, '["Art. 162"]'::jsonb, 'under_review', 'claude'
