insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Permitir que pessoa nas condições do art. 162 tome posse do veículo automotor e passe a conduzi-lo na via é infração com as mesmas características e penalidades do art. 162, com a medida administrativa do inciso III do art. 162.', '["Mesmas infração e penalidades do art. 162.","Retenção do veículo."]'::jsonb, '["Quem permite a posse também responde."]'::jsonb, 'O dono que deixa o carro com quem não tem CNH é autuado.', '["Assertiva que isenta quem permite a posse do veículo a não habilitado erra."]'::jsonb, '[]'::jsonb, '["Art. 163"]'::jsonb, 'under_review', 'claude'
