insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Recusar-se a ser submetido a teste, exame clínico, perícia ou outro procedimento que permita certificar influência de álcool ou outra substância psicoativa, na forma do art. 277, é infração gravíssima, com multa (dez vezes) e suspensão do direito de dirigir por doze meses, recolhimento do documento e retenção do veículo. A multa é aplicada em dobro na reincidência em até doze meses.', '["Recusa ao teste do bafômetro ou perícia.","Mesmas penalidades da direção sob influência de álcool.","Dobro da multa na reincidência."]'::jsonb, '["ATUALIZAÇÃO: infração incluída por lei posterior.","A recusa recebe as mesmas penalidades do art. 165."]'::jsonb, 'Quem se recusa ao bafômetro sofre a mesma penalidade de quem dirigiu alcoolizado.', '["Assertiva que isenta de penalidade administrativa quem se recusa ao bafômetro erra."]'::jsonb, '[]'::jsonb, '["Art. 165"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-165-a'
