insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Dirigir veículo sem realizar o exame toxicológico previsto no art. 148-A é infração gravíssima, com multa (cinco vezes) e, em caso de reincidência em até doze meses, multa (dez vezes) e suspensão do direito de dirigir. Se o condutor deixar de fazer o exame periódico, a infração se configura quando dirigir após o trigésimo dia do vencimento do prazo.', '["Infração gravíssima.","Multa (cinco vezes), dez vezes na reincidência.","Suspensão na reincidência.","Prazo de trinta dias após o vencimento do exame periódico."]'::jsonb, '["ATUALIZAÇÃO: infração incluída pela lei do exame toxicológico.","Multa CINCO vezes; reincidência em até doze meses: dez vezes e suspensão."]'::jsonb, 'O motorista de ônibus sem exame toxicológico na renovação é autuado.', '["Assertiva que isenta de multa a falta do exame toxicológico erra."]'::jsonb, '[]'::jsonb, '["Art. 148-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-165-b'
