insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Promover, na via, competição, eventos organizados, exibição e demonstração de perícia em manobra de veículo, ou deles participar como condutor, sem permissão da autoridade de trânsito é infração gravíssima, com multa (dez vezes), suspensão do direito de dirigir e apreensão do veículo, e medida administrativa de recolhimento do documento e remoção do veículo. As penalidades se aplicam aos promotores e aos condutores participantes, e a multa é em dobro na reincidência em doze meses.', '["Competição ou exibição sem permissão.","Aplica-se a promotores e condutores.","Mesmas penalidades da disputa de corrida."]'::jsonb, '["Promotores E condutores participantes respondem."]'::jsonb, 'O organizador do evento de manobras sem autorização é penalizado, assim como os condutores.', '["Assertiva que isenta o promotor do evento de penalidade erra."]'::jsonb, '[]'::jsonb, '["Art. 67"]'::jsonb, 'under_review', 'claude'
