on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Utilizar-se de veículo para demonstrar ou exibir manobra perigosa, mediante arrancada brusca, derrapagem ou frenagem com deslizamento ou arrastamento de pneus, é infração gravíssima, com multa (dez vezes), suspensão do direito de dirigir e apreensão do veículo, e medida administrativa de recolhimento do documento e remoção do veículo. A multa é em dobro na reincidência em doze meses.', '["Arrancada brusca, derrapagem ou frenagem com arrastamento.","Gravíssima, com suspensão e apreensão."]'::jsonb, '["Mesmas penalidades da disputa de corrida."]'::jsonb, 'Fazer cavalo de pau na via pública para exibição gera apreensão do veículo.', '["Assertiva que considera média a exibição de manobra perigosa erra: é gravíssima."]'::jsonb, '[]'::jsonb, '["Art. 173"]'::jsonb, 'under_review', 'claude'
