insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Deixar o condutor envolvido em sinistro com vítima de prestar ou providenciar socorro, podendo fazê-lo; de adotar providências para evitar perigo ao trânsito no local; de preservar o local, de forma a facilitar os trabalhos da polícia e da perícia; de remover o veículo quando determinado pela autoridade; ou de identificar-se ao policial e prestar as informações necessárias ao boletim de ocorrência, é infração gravíssima, com multa (cinco vezes) e suspensão do direito de dirigir, e recolhimento do documento de habilitação.', '["Cinco condutas omissivas após sinistro com vítima.","Gravíssima, multa (cinco vezes) e suspensão do direito de dirigir."]'::jsonb, '["Não confundir com o crime de omissão de socorro (art. 304).","ATUALIZAÇÃO: o termo \"acidente\" foi substituído por \"sinistro\" por lei posterior."]'::jsonb, 'Quem foge do local do sinistro sem socorrer a vítima comete infração gravíssima.', '["Assertiva que classifica como média a fuga do local do sinistro com vítima erra: é gravíssima."]'::jsonb, '[]'::jsonb, '["Art. 304"]'::jsonb, 'under_review', 'claude'
