insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Deixar o condutor envolvido em sinistro sem vítima de adotar providências para remover o veículo do local, quando necessária tal medida para assegurar a segurança e a fluidez do trânsito, é infração média, com penalidade de multa.', '["Sinistro sem vítima.","Infração média."]'::jsonb, '["Média, em sinistro SEM vítima."]'::jsonb, 'Deixar o carro batido bloqueando a via, sem vítimas, gera multa.', '["Assertiva que aplica a penalidade do art. 178 a sinistros com vítima erra: é para sinistros sem vítima."]'::jsonb, '[]'::jsonb, '["Art. 176"]'::jsonb, 'under_review', 'claude'
