select u.id, u.content_sha256, 'Ter seu veículo imobilizado na via por falta de combustível é infração média, com multa e a medida administrativa de remoção do veículo.', '["Infração média.","Multa e remoção do veículo."]'::jsonb, '["Média, com remoção do veículo."]'::jsonb, 'O carro parado por falta de combustível pode ser removido e gera multa.', '["Assertiva que classifica como leve a imobilização por falta de combustível erra: é média."]'::jsonb, '[]'::jsonb, '["Art. 27"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-180'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O estacionamento irregular é infração com gravidade variável, sempre com multa e remoção do veículo. É média estacionar nas esquinas e a menos de cinco metros do bordo da via transversal, em desacordo com as posições do Código, junto a hidrantes, em ponto de ônibus, impedindo a movimentação de outro veículo e onde houver guia rebaixada. É leve estacionar afastado da guia entre cinquenta centímetros e um metro, e nos acostamentos. É grave estacionar afastado da guia a mais de um metro, no passeio ou sobre faixa de pedestre, ciclovia ou ciclofaixa, em fila dupla, na área de cruzamento, e em viadutos, pontes e túneis. É gravíssima estacionar na pista de rolamento das estradas, rodovias, vias de trânsito rápido e vias com acostamento. Também há infrações específicas para vagas de idosos e pessoas com deficiência e para locais proibidos pela sinalização.', '["Média: esquinas, hidrantes, pontos de ônibus, guia rebaixada.","Leve: afastado da guia de meio a um metro; acostamentos.","Grave: fila dupla, passeio, faixa de pedestre, ciclovia, cruzamento, viadutos.","Gravíssima: pista de rolamento de estradas, rodovias e vias de trânsito rápido."]'::jsonb, '["Estacionar em fila dupla é infração GRAVE.","Estacionar a menos de cinco metros da esquina: média."]'::jsonb, 'O veículo em fila dupla gera multa grave e remoção.', '["Assertiva que classifica como leve o estacionamento em fila dupla erra: é grave."]'::jsonb, '[]'::jsonb, '["Art. 182"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-181'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Parar o veículo em local irregular é infração de menor gravidade que estacionar, sem a medida de remoção na maior parte dos casos. É média parar nas esquinas e a menos de cinco metros do bordo da via transversal, afastado da guia a mais de um metro, na área de cruzamento, em viadutos, pontes e túneis, na contramão e em local proibido pela sinalização. É leve parar afastado da guia de cinquenta centímetros a um metro, em desacordo com as posições do Código, no passeio ou faixa de pedestres. É grave parar na pista de rolamento das estradas e vias com acostamento e sobre ciclovia ou ciclofaixa.', '["Média: esquinas, cruzamento, viadutos, contramão, local proibido.","Leve: afastado entre meio e um metro; passeio e faixa de pedestres.","Grave: pista de rolamento das estradas e sobre ciclovia."]'::jsonb, '["Parar é menos grave que estacionar nos mesmos locais."]'::jsonb, 'Parar sobre a ciclovia é infração grave.', '["Assertiva que aplica remoção do veículo como medida padrão em todas as paradas irregulares erra."]'::jsonb, '[]'::jsonb, '["Art. 181"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-182'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Parar o veículo sobre a faixa de pedestres na mudança de sinal luminoso é infração média, com penalidade de multa.', '["Infração média.","Parar sobre a faixa na mudança de sinal."]'::jsonb, '["Média."]'::jsonb, 'Parar sobre a faixa de pedestres quando o sinal abre é infração.', '["Assertiva que classifica como gravíssima a parada sobre a faixa de pedestres na mudança de sinal erra: é média."]'::jsonb, '[]'::jsonb, '["Art. 70"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-183'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Transitar com o veículo na faixa ou pista da direita regulamentada como de circulação exclusiva para determinado tipo de veículo, exceto para acesso a imóveis lindeiros ou conversões à direita, é infração leve; na faixa ou pista da esquerda regulamentada como exclusiva, é infração grave; e na faixa ou via de trânsito exclusivo destinada aos veículos de transporte público coletivo, salvo força maior e autorização do poder público, é infração gravíssima, com multa e apreensão do veículo, e remoção.', '["Faixa exclusiva da direita: leve.","Faixa exclusiva da esquerda: grave.","Faixa exclusiva de transporte coletivo: gravíssima com apreensão."]'::jsonb, '["Faixa de ônibus: GRAVÍSSIMA, com apreensão e remoção."]'::jsonb, 'Dirigir na faixa exclusiva de ônibus gera multa gravíssima e apreensão do veículo.', '["Assertiva que classifica como leve o uso indevido da faixa de ônibus erra: é gravíssima."]'::jsonb, '[]'::jsonb, '["Art. 185"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-184'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Quando o veículo estiver em movimento, deixar de conservá-lo na faixa a ele destinada pela sinalização de regulamentação, exceto em situações de emergência, ou deixar de conservar nas faixas da direita os veículos lentos e de maior porte, é infração média, com penalidade de multa.', '["Manter o veículo na faixa destinada.","Veículos lentos e de maior porte nas faixas da direita.","Infração média."]'::jsonb, '["Média; exceção para emergência."]'::jsonb, 'O caminhão lento deve trafegar nas faixas da direita.', '["Assertiva que permite caminhões lentos na faixa da esquerda erra."]'::jsonb, '[]'::jsonb, '["Art. 184"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-185'
