insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Transitar em locais e horários não permitidos pela regulamentação estabelecida pela autoridade competente é infração média, com multa, para todos os tipos de veículos. O antigo inciso II, que tratava de veículos específicos como os de carga, foi revogado pela Lei nº 9.602, de 1998, e hoje todas as restrições de local e horário se enquadram no inciso I.', '["Infração média, para todos os tipos de veículos.","Inciso II revogado: todas as restrições se enquadram no inciso I."]'::jsonb, '["ATUALIZAÇÃO: o inciso II foi revogado pela Lei nº 9.602, de 1998; hoje só vale o inciso I.","Média, com quatro pontos, também para caminhões em restrição de circulação."]'::jsonb, 'O caminhão que circula em horário proibido pela placa é autuado no art. 187, I.', '["Assertiva que classifica como grave a circulação de caminhão em local ou horário proibido erra: o inciso II foi revogado e vale a infração média."]'::jsonb, '[]'::jsonb, '["Art. 12"]'::jsonb, 'under_review', 'claude'
