select u.id, u.content_sha256, 'Deixar de manter ligado, nas situações de atendimento de emergência, o sistema de iluminação intermitente dos veículos de polícia, de socorro de incêndio e salvamento, de fiscalização de trânsito e das ambulâncias, ainda que parados, é infração média, com multa.', '["Infração média.","Luz intermitente ligada em emergência."]'::jsonb, '["Dever dos veículos de emergência, mesmo parados."]'::jsonb, 'A ambulância parada no local da ocorrência mantém a luz intermitente.', '["Assertiva que dispensa a luz intermitente quando o veículo de emergência está parado erra."]'::jsonb, '[]'::jsonb, '["Art. 189"]'::jsonb, 'under_review', 'claude'
