insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Usar buzina em situação que não seja o simples toque breve como advertência, de forma prolongada e sucessiva a qualquer pretexto, entre as vinte e duas e as seis horas, em locais e horários proibidos pela sinalização ou em desacordo com os padrões do Contran é infração leve, com multa.', '["Infração leve.","Buzina fora do toque breve, prolongada, à noite ou em locais proibidos."]'::jsonb, '["Entre as vinte e duas e as seis horas."]'::jsonb, 'Buzinar de forma prolongada à noite é infração leve.', '["Assertiva que classifica como grave o uso indevido da buzina erra: é leve."]'::jsonb, '[]'::jsonb, '["Art. 41"]'::jsonb, 'under_review', 'claude'
