insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Usar no veículo equipamento com som em volume ou frequência que não sejam autorizados pelo Contran é infração grave, com multa e a medida administrativa de retenção do veículo para regularização.', '["Infração grave.","Retenção para regularização."]'::jsonb, '["Grave, com retenção."]'::jsonb, 'O som automotivo acima do limite gera multa grave.', '["Assertiva que classifica como leve o som acima do permitido erra: é grave."]'::jsonb, '[]'::jsonb, '["Art. 229"]'::jsonb, 'under_review', 'claude'
