select u.id, u.content_sha256, 'Usar indevidamente no veículo aparelho de alarme ou que produza sons e ruído que perturbem o sossego público, em desacordo com normas fixadas pelo Contran, é infração média, com multa e apreensão do veículo, e medida administrativa de remoção.', '["Infração média.","Multa e apreensão do veículo.","Remoção do veículo."]'::jsonb, '["Média, mas com apreensão do veículo."]'::jsonb, 'O alarme que dispara sem motivo e perturba o sossego pode gerar a apreensão.', '["Assertiva que prevê apenas multa simples erra: há apreensão do veículo."]'::jsonb, '[]'::jsonb, '["Art. 228"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-229'
