insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Conduzir veículo com lacre, inscrição do chassi, selo ou placa violados ou falsificados, transportando passageiros em compartimento de carga, com dispositivo antirradar, sem qualquer das placas, não registrado e licenciado, ou com placa ilegível é infração gravíssima, com multa e apreensão do veículo e remoção. Conduzir com cor ou característica alterada, sem inspeção obrigatória, sem equipamento obrigatório, com descarga livre, equipamento proibido, iluminação alterada, registrador viciado, publicidade no para-brisa, vidros cobertos por películas, cortinas fechadas, em mau estado de conservação ou sem acionar o limpador sob chuva é infração grave, com retenção para regularização. Sem autorização de condução de escolares: gravíssima, multa (cinco vezes). Com defeito de iluminação ou lâmpadas queimadas, ou em desacordo com o tempo de direção do art. 67-C: média.', '["Gravíssima: identificação violada, sem placa, não licenciado, antirradar.","Grave: sem equipamento obrigatório, películas, mau estado, sem limpador sob chuva.","Escolar sem autorização: gravíssima, multa cinco vezes.","Média: lâmpada queimada e descumprimento do tempo de direção."]'::jsonb, '["Dispositivo ANTIRRADAR: gravíssima, com apreensão.","Descumprir o tempo de direção do art. 67-C: média, com retenção para o descanso.","Condutor estrangeiro: liberação condicionada ao pagamento ou depósito da multa."]'::jsonb, 'Dirigir sem a placa dianteira gera multa gravíssima e apreensão do veículo.', '["Assertiva que classifica como grave o uso de antirradar erra: é gravíssima."]'::jsonb, '[]'::jsonb, '["Art. 67-C"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-230'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Transitar com o veículo danificando a via ou derramando ou arrastando sobre ela carga, combustível, lubrificante ou objeto que possa causar sinistro é infração gravíssima, com multa e retenção para regularização. Produzir fumaça, gases ou partículas acima dos níveis do Contran, ou ultrapassar dimensões legais sem autorização, é infração grave. Com excesso de peso, a infração é média, com multa acrescida por faixa de duzentos quilogramas excedentes (de R$ 5,32 até R$ 53,20), com retenção e transbordo da carga. Com lotação excedente ou fazendo transporte remunerado sem licença: gravíssima; desligado ou desengrenado em declive: média; excedendo a capacidade máxima de tração: de média a gravíssima.', '["Gravíssima: danificar a via e derramar carga ou combustível; transporte remunerado sem licença.","Grave: fumaça acima do limite e dimensões excedentes sem autorização.","Média: excesso de peso, desengrenado em declive.","Excesso de peso com acréscimo por faixa de duzentos quilogramas."]'::jsonb, '["Excesso de peso: multa acrescida por faixa de peso; retenção e transbordo.","Valores em reais dessa tabela constam do texto legal; confira eventual atualização."]'::jsonb, 'O caminhão com excesso de peso é retido para transbordo da carga excedente.', '["Assertiva que classifica como leve o excesso de peso erra: é média, com acréscimo por faixa."]'::jsonb, '[]'::jsonb, '["Art. 99"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-231'
