insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Conduzir veículo sem os documentos de porte obrigatório referidos no Código é infração leve, com multa e a medida administrativa de retenção do veículo até a apresentação do documento.', '["Infração leve.","Retenção do veículo até apresentar o documento."]'::jsonb, '["Leve, mas com retenção até a apresentação do documento.","Não gera pontuação no prontuário, conforme o art. 259."]'::jsonb, 'Dirigir sem portar o documento exigido, sem possibilidade de consulta ao sistema, gera a retenção.', '["Assertiva que classifica como média a falta de porte de documento obrigatório erra: é leve."]'::jsonb, '[]'::jsonb, '["Art. 133"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-232'
