insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Deixar de efetuar o registro de veículo no prazo de trinta dias junto ao órgão executivo de trânsito, ocorridas as hipóteses do art. 123, é infração média, com multa e a medida administrativa de remoção do veículo.', '["Infração média.","Prazo de trinta dias.","Remoção do veículo."]'::jsonb, '["Trinta dias, como no art. 123."]'::jsonb, 'Quem não transfere o veículo em trinta dias é autuado.', '["Assertiva que fixa em sessenta dias o prazo para o registro erra: são trinta dias."]'::jsonb, '[]'::jsonb, '["Art. 123"]'::jsonb, 'under_review', 'claude'
