select u.id, u.content_sha256, 'Deixar de manter acesas, à noite, as luzes de posição, quando o veículo estiver parado para fins de embarque ou desembarque de passageiros e carga ou descarga de mercadorias, é infração média, com multa.', '["Infração média.","Luzes de posição acesas à noite, com o veículo parado para embarque ou carga."]'::jsonb, '["Média."]'::jsonb, 'O veículo que descarrega à noite mantém as luzes de posição acesas.', '["Assertiva que dispensa as luzes de posição com o veículo parado erra."]'::jsonb, '[]'::jsonb, '["Art. 40"]'::jsonb, 'under_review', 'claude'
