insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Com o veículo em movimento, deixar de manter acesa a luz baixa durante a noite; de dia, em túneis e sob chuva, neblina ou cerração; de dia, no caso de transporte coletivo em faixas exclusivas e de motocicletas, motonetas e ciclomotores; ou de dia, em rodovias de pista simples fora de perímetro urbano, para veículos sem luzes de rodagem diurna, é infração média, com multa. Deixar a placa traseira não iluminada à noite também é média. Veículo de transporte coletivo ou escolar com a porta aberta durante o trânsito é infração gravíssima, com retenção do veículo.', '["Luz baixa acesa em diversas situações: média.","Placa traseira iluminada à noite.","Porta aberta em coletivo ou escolar em movimento: gravíssima."]'::jsonb, '["Motocicletas devem manter a luz baixa acesa também de dia.","Porta aberta de ônibus ou transporte escolar em movimento: gravíssima."]'::jsonb, 'A motocicleta circula de dia com o farol baixo aceso.', '["Assertiva que dispensa o farol aceso de dia para motocicletas erra."]'::jsonb, '[]'::jsonb, '["Art. 40"]'::jsonb, 'under_review', 'claude'
