insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Utilizar as luzes do veículo de modo inadequado é infração média, com multa: usar o pisca-alerta, exceto em imobilizações ou situações de emergência; e usar as luzes baixa e alta de forma intermitente, exceto a curtos intervalos para advertir que se pretende ultrapassar, em imobilizações ou emergências com pisca-alerta, ou quando a sinalização determinar o uso do pisca-alerta.', '["Infração média.","Pisca-alerta só em imobilização ou emergência.","Alternar farol alto e baixo só em casos permitidos."]'::jsonb, '["Pisca-alerta em movimento sem emergência é infração."]'::jsonb, 'Ligar o pisca-alerta para andar mais devagar sem emergência gera multa.', '["Assertiva que permite o uso do pisca-alerta em movimento sempre que o condutor quiser erra."]'::jsonb, '[]'::jsonb, '["Art. 40"]'::jsonb, 'under_review', 'claude'
