insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Dirigir o veículo com o braço do lado de fora; transportando pessoas, animais ou volume à sua esquerda ou entre os braços e pernas; com incapacidade física ou mental temporária que comprometa a segurança; usando calçado que não se firme nos pés; com apenas uma das mãos, exceto para sinais, mudar a marcha ou acionar equipamentos; ou utilizando fones nos ouvidos conectados a aparelhagem sonora ou a telefone celular é infração média, com multa. Realizar cobrança de tarifa com o veículo em movimento também é média. Segurar ou manusear o telefone celular enquanto dirige é infração gravíssima.', '["Média: braço de fora, calçado inadequado, uma só mão, fones de ouvido.","Gravíssima: segurar ou manusear o celular.","Cobrança de tarifa em movimento: média."]'::jsonb, '["O inciso V (apenas uma das mãos) vira GRAVÍSSIMA se o condutor estiver segurando ou manuseando o celular.","Fones nos ouvidos: média."]'::jsonb, 'Dirigir com o celular na mão é infração gravíssima.', '["Assertiva que classifica como média a condução segurando o celular erra: é gravíssima."]'::jsonb, '[]'::jsonb, '["Art. 28"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-252'
