insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Bloquear a via com veículo é infração gravíssima, com multa e apreensão do veículo, e medida administrativa de remoção do veículo.', '["Infração gravíssima.","Apreensão do veículo."]'::jsonb, '["Gravíssima, com apreensão."]'::jsonb, 'Parar o veículo bloqueando a via gera apreensão.', '["Assertiva que classifica como média o bloqueio da via erra."]'::jsonb, '[]'::jsonb, '["Art. 253-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-253'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Usar qualquer veículo para, deliberadamente, interromper, restringir ou perturbar a circulação na via sem autorização do órgão de trânsito é infração gravíssima, com multa (vinte vezes) e suspensão do direito de dirigir por doze meses, e remoção do veículo. Aplica-se multa agravada em sessenta vezes aos organizadores da conduta, e multa em dobro na reincidência em doze meses. As penalidades se aplicam a pessoas físicas ou jurídicas, devendo a autoridade restabelecer de imediato a circulação.', '["Infração gravíssima.","Multa (vinte vezes) e suspensão por doze meses.","Organizadores: multa agravada em sessenta vezes.","Dobro na reincidência."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior.","Multa de VINTE vezes; organizadores: SESSENTA vezes."]'::jsonb, 'Quem organiza o bloqueio deliberado da rodovia sofre a multa agravada.', '["Assertiva que isenta os organizadores da multa agravada erra."]'::jsonb, '[]'::jsonb, '["Art. 253"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-253-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É proibido ao pedestre permanecer ou andar nas pistas de rolamento, exceto para cruzá-las onde for permitido; cruzar pistas em viadutos, pontes ou túneis, salvo onde exista permissão; atravessar a via dentro das áreas de cruzamento, salvo com sinalização; utilizar a via em agrupamentos capazes de perturbar o trânsito, salvo licença; andar fora da faixa própria, passarela ou passagem; e desobedecer à sinalização específica. A infração é leve, com multa de cinquenta por cento do valor da infração leve.', '["Seis condutas proibidas ao pedestre.","Infração leve.","Multa de cinquenta por cento do valor da leve."]'::jsonb, '["Multa de 50% do valor da infração leve."]'::jsonb, 'O pedestre que anda no meio da pista comete infração.', '["Assertiva que isenta o pedestre de qualquer infração de trânsito erra."]'::jsonb, '[]'::jsonb, '["Art. 69"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-254'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Conduzir bicicleta em passeios onde não seja permitida a circulação dela, ou de forma agressiva, em desacordo com o parágrafo único do art. 59, é infração média, com multa e remoção da bicicleta mediante recibo para o pagamento da multa.', '["Infração média.","Remoção da bicicleta mediante recibo."]'::jsonb, '["Média, com remoção da bicicleta."]'::jsonb, 'Pedalar de forma agressiva na calçada gera a multa.', '["Assertiva que isenta o ciclista de infração ao pedalar na calçada proibida erra."]'::jsonb, '[]'::jsonb, '["Art. 59"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-255'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A autoridade de trânsito, na esfera de sua competência e dentro de sua circunscrição, aplica às infrações as penalidades de advertência por escrito, multa, suspensão do direito de dirigir, cassação da CNH, cassação da Permissão para Dirigir e frequência obrigatória em curso de reciclagem. A aplicação das penalidades não elide as punições dos crimes de trânsito. A imposição da penalidade é comunicada aos órgãos de trânsito responsáveis pelo licenciamento do veículo e pela habilitação do condutor.', '["Rol de penalidades.","Independência entre a esfera administrativa e a penal.","Comunicação da penalidade aos órgãos competentes."]'::jsonb, '["Penalidade administrativa não exclui a punição penal.","ATUALIZAÇÃO: a apreensão do veículo e outras medidas constam em artigos específicos."]'::jsonb, 'O condutor responde pela multa e pelo crime de trânsito, quando houver.', '["Assertiva que exclui o processo penal quando houver penalidade administrativa erra."]'::jsonb, '[]'::jsonb, '["Art. 161"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-256'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As penalidades são impostas ao condutor, ao proprietário do veículo, ao embarcador e ao transportador, salvo os casos de descumprimento de obrigações impostas a pessoas expressamente mencionadas no Código. Quando há responsabilidade solidária, proprietário e condutor recebem concomitantemente as penalidades. Ao proprietário cabe sempre a responsabilidade pela infração referente à prévia regularização e às formalidades do veículo. O condutor responde pelas infrações decorrentes de atos praticados na direção.', '["Penalidades ao condutor, proprietário, embarcador e transportador.","Responsabilidade solidária.","Proprietário responde pela regularização do veículo.","Condutor responde pelos atos na direção."]'::jsonb, '["Quem responde depende da natureza da infração.","O proprietário que não identifica o condutor responde pela infração, nos termos do Código."]'::jsonb, 'A multa por veículo sem licenciamento recai sobre o proprietário.', '["Assertiva que atribui sempre ao condutor a responsabilidade pela falta de licenciamento erra."]'::jsonb, '[]'::jsonb, '["Art. 258"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-257'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As infrações punidas com multa classificam-se em quatro categorias: gravíssima, com multa de R$ 293,47; grave, com R$ 195,23; média, com R$ 130,16; e leve, com R$ 88,38. Quando se tratar de multa agravada, o fator multiplicador ou índice adicional específico é o previsto no Código.', '["Gravíssima: R$ 293,47.","Grave: R$ 195,23.","Média: R$ 130,16.","Leve: R$ 88,38."]'::jsonb, '["Valores previstos no texto legal; confira eventual atualização por lei posterior.","Multa agravada segue o fator previsto no artigo da infração."]'::jsonb, 'A multa por avançar o sinal vermelho é de R$ 293,47, sem agravantes.', '["Assertiva que fixa em R$ 195,23 a multa da infração gravíssima erra: esse é o valor da grave."]'::jsonb, '[]'::jsonb, '["Art. 259"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-258'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A cada infração cometida são computados pontos: sete pontos para a gravíssima, cinco para a grave, quatro para a média e três para a leve. Ao condutor identificado é atribuída a pontuação pelas infrações de sua responsabilidade, exceto as praticadas por passageiros usuários do serviço de transporte rodoviário de passageiros em viagens de longa distância, as previstas nos arts. 221, 230 (incisos VII e XXI), 232, 233, 240 e 241, e as puníveis de forma específica com suspensão do direito de dirigir.', '["Gravíssima: sete pontos.","Grave: cinco pontos.","Média: quatro pontos.","Leve: três pontos.","Infrações que não pontuam."]'::jsonb, '["Sete, cinco, quatro e três pontos.","Algumas infrações administrativas não geram pontos."]'::jsonb, 'A infração média soma quatro pontos no prontuário.', '["Assertiva que atribui seis pontos à infração gravíssima erra: são sete."]'::jsonb, '[]'::jsonb, '["Art. 261"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-259'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As multas são impostas e arrecadadas pelo órgão ou entidade de trânsito com circunscrição sobre a via onde ocorreu a infração. As multas por infração em unidade da Federação diversa da do licenciamento do veículo são arrecadadas e compensadas na forma do Contran e podem ser comunicadas ao órgão de licenciamento, que providencia a notificação. Para veículo licenciado no exterior, há procedimento próprio.', '["Imposição e arrecadação pelo órgão da via.","Compensação entre unidades da Federação.","Veículo licenciado no exterior."]'::jsonb, '["Quem arrecada é o órgão com circunscrição sobre a via."]'::jsonb, 'A multa na rodovia estadual é arrecadada pelo órgão rodoviário daquele estado.', '["Assertiva que atribui a arrecadação ao órgão de registro do veículo erra."]'::jsonb, '[]'::jsonb, '["Art. 258"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-260'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A suspensão do direito de dirigir é imposta quando o infrator atingir, em doze meses, vinte pontos, se constarem duas ou mais infrações gravíssimas; trinta pontos, se constar uma infração gravíssima; ou quarenta pontos, se não constar nenhuma gravíssima; e por infrações que preveem a suspensão de forma específica. O prazo de suspensão é de seis meses a um ano e, na reincidência em doze meses, de oito meses a dois anos, no caso da pontuação; e de dois a oito meses nos demais casos. A CNH é devolvida após cumprida a penalidade e o curso de reciclagem. A suspensão elimina os pontos computados. Para o condutor que exerce atividade remunerada ao veículo, a suspensão por pontos ocorre apenas ao atingir quarenta pontos.', '["Limites de pontos: 20, 30 ou 40 em doze meses.","Prazos de suspensão por pontuação: seis meses a um ano.","Reincidência: oito meses a dois anos.","Condutor profissional: quarenta pontos."]'::jsonb, '["ATUALIZAÇÃO: os limites de pontos foram alterados por lei posterior; confira o texto vigente.","Vinte pontos (duas gravíssimas), trinta (uma gravíssima) e quarenta (nenhuma)."]'::jsonb, 'O condutor com uma infração gravíssima e 30 pontos em doze meses tem a CNH suspensa.', '["Assertiva que fixa em vinte pontos o limite para quem não tem nenhuma infração gravíssima erra: são quarenta."]'::jsonb, '[]'::jsonb, '["Art. 259"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-261'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A cassação do documento de habilitação ocorre quando, suspenso o direito de dirigir, o infrator conduzir qualquer veículo; no caso de reincidência, em doze meses, das infrações do inciso III do art. 162 e dos arts. 163, 164, 165, 173, 174 e 175; e quando condenado judicialmente por delito de trânsito, observado o art. 160. Constatada irregularidade na expedição do documento, a autoridade promove seu cancelamento. Decorridos dois anos da cassação, o infrator pode requerer a reabilitação, submetendo-se a todos os exames necessários à habilitação.', '["Dirigir com a CNH suspensa.","Reincidência em doze meses em infrações graves específicas.","Condenação judicial por delito de trânsito.","Reabilitação após dois anos."]'::jsonb, '["Reabilitação só após DOIS anos da cassação."]'::jsonb, 'Quem dirige durante a suspensão tem a CNH cassada.', '["Assertiva que permite a reabilitação seis meses após a cassação erra: são dois anos."]'::jsonb, '[]'::jsonb, '["Art. 261"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-263'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As penalidades de suspensão do direito de dirigir e de cassação do documento de habilitação são aplicadas por decisão fundamentada da autoridade de trânsito competente, em processo administrativo, assegurado ao infrator amplo direito de defesa.', '["Decisão fundamentada.","Processo administrativo.","Ampla defesa."]'::jsonb, '["Ampla defesa é indispensável."]'::jsonb, 'A suspensão só é aplicada após processo com defesa do condutor.', '["Assertiva que dispensa o processo administrativo na suspensão do direito de dirigir erra."]'::jsonb, '[]'::jsonb, '["Art. 261"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-265'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Quando o infrator comete, simultaneamente, duas ou mais infrações, são-lhe aplicadas, cumulativamente, as respectivas penalidades.', '["Cumulação das penalidades."]'::jsonb, '["Cumulativas, sem absorção."]'::jsonb, 'Quem avança o sinal e dirige sem cinto recebe as duas multas.', '["Assertiva que aplica só a penalidade da infração mais grave erra."]'::jsonb, '[]'::jsonb, '["Art. 256"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-266'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Deve ser imposta a penalidade de advertência por escrito à infração de natureza leve ou média, passível de ser punida com multa, caso o infrator não tenha cometido nenhuma outra infração nos últimos doze meses.', '["Advertência por escrito para infração leve ou média.","Sem outra infração nos últimos doze meses."]'::jsonb, '["Só infrações leve ou média; exige prontuário limpo por doze meses."]'::jsonb, 'O condutor sem infrações no último ano recebe advertência em vez de multa por infração leve.', '["Assertiva que aplica advertência a infração gravíssima erra."]'::jsonb, '[]'::jsonb, '["Art. 256"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-267'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O infrator é submetido a curso de reciclagem, na forma do Contran, quando suspenso do direito de dirigir; quando se envolver em sinistro grave para o qual haja contribuído, independentemente de processo judicial; quando condenado judicialmente por delito de trânsito; e a qualquer tempo, se for constatado que o condutor está colocando em risco a segurança do trânsito. Nos casos de sinistro grave, condenação e risco, o infrator é submetido também à avaliação psicológica.', '["Reciclagem na suspensão, sinistro grave, condenação e risco.","Avaliação psicológica em três hipóteses."]'::jsonb, '["Avaliação psicológica adicional nos incisos III, IV e V."]'::jsonb, 'O condutor que causa sinistro grave faz reciclagem e avaliação psicológica.', '["Assertiva que dispensa a avaliação psicológica no curso de reciclagem após sinistro grave erra."]'::jsonb, '[]'::jsonb, '["Art. 261"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-268'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Fica criado o Registro Nacional Positivo de Condutores (RNPC), administrado pelo órgão máximo executivo de trânsito da União, para cadastrar os condutores que não cometeram infração de trânsito sujeita à pontuação nos últimos doze meses, conforme o Contran. É atualizado mensalmente. A abertura do cadastro requer autorização prévia e expressa do potencial cadastrado. A exclusão ocorre por solicitação do cadastrado ou quando lhe for atribuída infração pontuável, entre outras hipóteses.', '["Cadastro de bons condutores.","Atualização mensal.","Abertura com autorização prévia e expressa."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior.","Cadastro voluntário."]'::jsonb, 'O condutor sem infração pontuável em doze meses pode aderir ao cadastro.', '["Assertiva que torna obrigatória a inscrição de todos os condutores no RNPC erra."]'::jsonb, '[]'::jsonb, '["Art. 259"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-268-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A autoridade de trânsito ou seus agentes adotam as medidas administrativas de retenção do veículo, remoção do veículo, recolhimento da CNH, da Permissão para Dirigir, do Certificado de Registro e do Certificado de Licenciamento Anual, transbordo do excesso de carga, teste de dosagem de alcoolemia ou perícia de substância entorpecente, recolhimento de animais soltos nas vias e realização de exames de aptidão e de direção. A prioridade é a proteção à vida e à incolumidade física da pessoa, e as medidas administrativas não elidem as penalidades, possuindo caráter complementar. São documentos de habilitação a CNH, a Permissão para Dirigir e a Autorização para Conduzir Ciclomotor.', '["Rol de medidas administrativas.","Prioridade: proteção à vida e à incolumidade física.","Caráter complementar às penalidades.","Documentos de habilitação."]'::jsonb, '["Medidas administrativas COMPLEMENTAM as penalidades."]'::jsonb, 'A retenção do veículo não exclui a multa.', '["Assertiva que substitui a multa pela medida administrativa erra: elas se somam."]'::jsonb, '[]'::jsonb, '["Art. 270"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-269'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O veículo pode ser retido nos casos expressos no Código. Se a irregularidade puder ser sanada no local, o veículo é liberado tão logo regularizada. Se não for possível, desde que ofereça condições de segurança, é liberado e entregue a condutor habilitado, mediante recolhimento do Certificado de Licenciamento Anual, com prazo razoável não superior a trinta dias para regularizar. Não se apresentando condutor habilitado, o veículo é removido ao depósito. A critério do agente, não se faz a retenção imediata de transporte coletivo com passageiros, ou de veículo com produto perigoso ou perecível, desde que ofereça condições de segurança.', '["Liberação após regularização no local.","Prazo de até trinta dias com recolhimento do CRLV.","Remoção ao depósito sem condutor habilitado.","Exceção para transporte coletivo e carga perigosa ou perecível."]'::jsonb, '["Prazo não superior a TRINTA dias para regularizar."]'::jsonb, 'O veículo com falha sanável é liberado, com prazo de até trinta dias para regularização.', '["Assertiva que fixa em sessenta dias o prazo para regularizar o veículo retido erra: são, no máximo, trinta dias."]'::jsonb, '[]'::jsonb, '["Art. 271"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-270'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O veículo é removido, nos casos previstos no Código, para o depósito fixado pelo órgão competente. A restituição só ocorre mediante prévio pagamento de multas, taxas e despesas com remoção e estada, além de outros encargos. A liberação é condicionada ao reparo de qualquer componente ou equipamento obrigatório que não esteja em perfeito estado, podendo o veículo ser liberado para reparo na forma transportada se o conserto não puder ser feito no depósito.', '["Remoção ao depósito.","Pagamento prévio de multas, taxas e despesas.","Reparo de equipamentos obrigatórios."]'::jsonb, '["Restituição só após pagar multas e despesas."]'::jsonb, 'Para retirar o carro do pátio, o proprietário paga multas e custos de remoção e estada.', '["Assertiva que libera o veículo removido sem o pagamento das despesas erra."]'::jsonb, '[]'::jsonb, '["Art. 270"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-271'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O recolhimento da CNH e da Permissão para Dirigir se dá mediante recibo, além dos casos previstos no Código, quando houver suspeita de inautenticidade ou adulteração.', '["Recolhimento mediante recibo.","Suspeita de inautenticidade ou adulteração."]'::jsonb, '["Sempre mediante recibo."]'::jsonb, 'O agente recolhe a CNH suspeita de falsidade e entrega recibo.', '["Assertiva que dispensa o recibo no recolhimento da CNH erra."]'::jsonb, '[]'::jsonb, '["Art. 238"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-272'
