insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O recolhimento do Certificado de Registro se dá mediante recibo, além dos casos previstos no Código, quando houver suspeita de inautenticidade ou adulteração, ou se, alienado o veículo, não for transferida sua propriedade no prazo de trinta dias.', '["Recolhimento mediante recibo.","Suspeita de adulteração.","Falta de transferência em trinta dias."]'::jsonb, '["Trinta dias para transferir após a venda."]'::jsonb, 'O CRV é recolhido se o veículo vendido não é transferido em trinta dias.', '["Assertiva que fixa em sessenta dias o prazo para transferir após a alienação erra: são trinta dias."]'::jsonb, '[]'::jsonb, '["Art. 123"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-273'
