insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O recolhimento do Certificado de Licenciamento Anual se dá mediante recibo, além dos casos previstos no Código, quando houver suspeita de inautenticidade ou adulteração, se o prazo de licenciamento estiver vencido, ou no caso de retenção do veículo, se a irregularidade não puder ser sanada no local.', '["Suspeita de adulteração.","Licenciamento vencido.","Retenção sem regularização no local."]'::jsonb, '["Mediante recibo."]'::jsonb, 'Com o licenciamento vencido, o CRLV é recolhido mediante recibo.', '["Assertiva que dispensa o recibo no recolhimento do CRLV erra."]'::jsonb, '[]'::jsonb, '["Art. 270"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-274'
