insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O transbordo da carga com peso excedente é condição para que o veículo possa prosseguir viagem e é efetuado às expensas do proprietário do veículo, sem prejuízo da multa aplicável. Não sendo possível desde logo, o veículo é recolhido ao depósito e liberado após sanada a irregularidade e pagas as despesas de remoção e estada.', '["Transbordo como condição para prosseguir.","Custo do proprietário.","Recolhimento ao depósito se não for possível."]'::jsonb, '["Custo do transbordo recai sobre o proprietário."]'::jsonb, 'O caminhão com excesso de peso só segue viagem após o transbordo.', '["Assertiva que isenta o proprietário do custo do transbordo erra."]'::jsonb, '[]'::jsonb, '["Art. 231"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-275'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Qualquer concentração de álcool por litro de sangue ou por litro de ar alveolar sujeita o condutor às penalidades do art. 165. O Contran disciplina as margens de tolerância quando a infração for apurada por meio de aparelho de medição, observada a legislação metrológica.', '["Qualquer concentração de álcool.","Margens de tolerância pelo Contran para aparelhos."]'::jsonb, '["Tolerância zero: não há limite mínimo de concentração.","Margem de tolerância do aparelho é definida pelo Contran."]'::jsonb, 'Mesmo uma pequena concentração de álcool configura a infração do art. 165.', '["Assertiva que admite uma concentração mínima de álcool sem infração erra."]'::jsonb, '[{"termo":"Tolerância zero","significado":"Qualquer concentração de álcool configura infração administrativa."}]'::jsonb, '["Art. 165"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-276'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O condutor de veículo automotor envolvido em sinistro de trânsito ou que for alvo de fiscalização pode ser submetido a teste, exame clínico, perícia ou outro procedimento que, por meios técnicos ou científicos, na forma do Contran, permita certificar influência de álcool ou outra substância psicoativa que determine dependência. A infração do art. 165 também pode ser caracterizada mediante imagem, vídeo, constatação de sinais de alteração da capacidade psicomotora ou outras provas admitidas em direito.', '["Testes, exames e perícias.","Infração do art. 165 comprovável por imagem, vídeo e sinais."]'::jsonb, '["A infração pode ser provada mesmo sem o bafômetro.","Recusar ao teste é infração própria (art. 165-A)."]'::jsonb, 'O vídeo mostrando sinais de embriaguez pode comprovar a infração.', '["Assertiva que só admite o bafômetro como prova da embriaguez erra."]'::jsonb, '[]'::jsonb, '["Art. 165-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-277'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O condutor que se evadir da fiscalização, não submetendo o veículo à pesagem obrigatória nos pontos de pesagem fixos ou móveis, sofre a penalidade do art. 209, além da obrigação de retornar ao ponto de evasão para a pesagem. Em caso de fuga à ação policial, a apreensão do veículo se dá tão logo seja localizado, aplicando-se também as penalidades do art. 210.', '["Evasão da pesagem: art. 209 e retorno ao ponto de pesagem.","Fuga à ação policial: apreensão e art. 210."]'::jsonb, '["Dois efeitos: penalidade e obrigação de voltar à pesagem."]'::jsonb, 'O caminhoneiro que desvia da balança retorna ao posto para ser pesado.', '["Assertiva que dispensa o retorno do condutor ao ponto de pesagem erra."]'::jsonb, '[]'::jsonb, '["Art. 209"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-278'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O condutor que usar veículo para a prática dos crimes de receptação, descaminho ou contrabando, condenado em decisão transitada em julgado, tem cassado seu documento de habilitação ou é proibido de obter a habilitação pelo prazo de cinco anos. O condenado pode requerer reabilitação, submetendo-se a todos os exames. No caso de preso em flagrante, o juiz pode decretar, como medida cautelar, a suspensão da habilitação ou a proibição de sua obtenção.', '["Cassação ou proibição por cinco anos.","Reabilitação mediante exames.","Cautelar na prisão em flagrante."]'::jsonb, '["Prazo de cinco anos.","ATUALIZAÇÃO: artigo incluído por lei posterior."]'::jsonb, 'O motorista condenado por contrabando com o veículo perde a habilitação por cinco anos.', '["Assertiva que fixa em um ano o prazo da proibição erra: são cinco anos."]'::jsonb, '[]'::jsonb, '["Art. 294"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-278-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Em caso de sinistro com vítima envolvendo veículo equipado com registrador instantâneo de velocidade e tempo, somente o perito oficial encarregado do levantamento pericial pode retirar o disco ou a unidade armazenadora do registro.', '["Só o perito oficial retira o disco ou a unidade do registrador."]'::jsonb, '["Preserva a prova do tacógrafo."]'::jsonb, 'Após o sinistro com vítima, só o perito retira o disco do tacógrafo.', '["Assertiva que permite ao condutor retirar o disco do tacógrafo após o sinistro erra."]'::jsonb, '[]'::jsonb, '["Art. 105"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-279'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O veículo em estado de abandono ou sinistrado pode ser removido para o depósito fixado pelo órgão competente, independentemente da existência de infração, nos termos da regulamentação do Contran. A remoção do veículo sinistrado é realizada quando não houver responsável por ele no local. Aplicam-se as disposições do art. 328, sem prejuízo das demais disposições do Código.', '["Remoção de veículo abandonado ou sinistrado.","Independe de infração.","Veículo sinistrado: quando não houver responsável no local."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior."]'::jsonb, 'O carro abandonado na via é removido ao depósito sem que haja infração.', '["Assertiva que exige infração para remover veículo abandonado erra."]'::jsonb, '[]'::jsonb, '["Art. 328"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-279-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ocorrendo infração, lavra-se auto de infração com a tipificação da infração; local, data e hora; caracteres da placa, marca e espécie do veículo; o prontuário do condutor, sempre que possível; a identificação do órgão e da autoridade, agente ou equipamento que comprovou a infração; e a assinatura do infrator, sempre que possível, valendo esta como notificação. A infração é comprovada por declaração da autoridade ou do agente, por aparelho eletrônico, equipamento audiovisual ou outro meio tecnológico regulamentado pelo Contran. O agente pode ser servidor civil ou policial militar designado pela autoridade de trânsito.', '["Elementos do auto de infração.","Comprovação por declaração, equipamento eletrônico ou meio tecnológico.","Agente civil ou policial militar designado."]'::jsonb, '["A assinatura do infrator vale como notificação, quando possível."]'::jsonb, 'O radar registra a infração e identifica o equipamento no auto.', '["Assertiva que exige sempre a assinatura do infrator no auto de infração erra: é sempre que possível."]'::jsonb, '[{"termo":"Auto de infração","significado":"Documento que registra a infração de trânsito constatada."}]'::jsonb, '["Art. 281"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-280'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A autoridade de trânsito julga a consistência do auto de infração e aplica a penalidade cabível. O auto é arquivado e seu registro julgado insubsistente se for considerado inconsistente ou irregular ou se, no prazo máximo de trinta dias, não for expedida a notificação da autuação. O prazo para a notificação das penalidades de suspensão do direito de dirigir e de cassação conta-se da instauração do processo destinado à aplicação dessas penalidades.', '["Julgamento da consistência do auto.","Arquivamento se inconsistente.","Notificação da autuação em até trinta dias."]'::jsonb, '["Trinta dias para a notificação da autuação, sob pena de arquivamento."]'::jsonb, 'Sem notificação em trinta dias, o auto de infração é arquivado.', '["Assertiva que fixa em sessenta dias o prazo para a notificação da autuação erra: são trinta dias."]'::jsonb, '[]'::jsonb, '["Art. 282"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-281'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Na notificação de autuação e no auto de infração, quando valer como notificação, deve constar o prazo para apresentação de defesa prévia, que não será inferior a trinta dias, contado da data de expedição da notificação.', '["Prazo de defesa prévia de, no mínimo, trinta dias."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior.","Mínimo de trinta dias."]'::jsonb, 'A notificação informa que o condutor tem ao menos trinta dias para a defesa prévia.', '["Assertiva que admite prazo de defesa prévia inferior a trinta dias erra."]'::jsonb, '[]'::jsonb, '["Art. 282"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-281-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Caso a defesa prévia seja indeferida ou não seja apresentada no prazo, é aplicada a penalidade e expedida notificação ao proprietário do veículo ou ao infrator, por remessa postal ou meio tecnológico que assegure a ciência. A notificação devolvida por desatualização de endereço ou recusa é válida para todos os efeitos. Quando a multa é imposta ao condutor, a notificação é encaminhada ao proprietário, responsável pelo pagamento. Da notificação constará a data do término do prazo para recurso, não inferior a trinta dias, que será também a data de recolhimento da multa. As notificações das penalidades do art. 256 têm prazo de expedição de cento e oitenta dias.', '["Notificação da penalidade após o indeferimento ou a falta de defesa.","Notificação devolvida por endereço desatualizado é válida.","Prazo de recurso de, no mínimo, trinta dias.","Expedição das notificações em cento e oitenta dias."]'::jsonb, '["Notificação devolvida por endereço desatualizado: VÁLIDA.","ATUALIZAÇÃO: o rito de defesa prévia foi incluído por lei posterior."]'::jsonb, 'A notificação devolvida por mudança de endereço não invalida a penalidade.', '["Assertiva que invalida a notificação devolvida por endereço desatualizado erra."]'::jsonb, '[]'::jsonb, '["Art. 281-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-282'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O órgão responsável pela autuação deve oferecer ao proprietário ou condutor autuado a opção de notificação por meio eletrônico, na forma do Contran. O proprietário e o condutor mantêm o cadastro atualizado no órgão executivo de trânsito do Estado ou do Distrito Federal. Nessa hipótese, o proprietário ou condutor é considerado notificado trinta dias após a inclusão da informação no sistema eletrônico e o envio da mensagem.', '["Opção de notificação eletrônica.","Cadastro atualizado.","Considerado notificado trinta dias após a inclusão no sistema."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior.","Notificado após TRINTA dias."]'::jsonb, 'O condutor aderente ao sistema eletrônico é considerado notificado trinta dias após o envio.', '["Assertiva que considera notificado o condutor no mesmo dia da mensagem erra: são trinta dias."]'::jsonb, '[]'::jsonb, '["Art. 284"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-282-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O pagamento da multa pode ser efetuado até a data do vencimento expressa na notificação, por oitenta por cento do seu valor. Se o infrator declarar, pelo sistema de notificação eletrônica, a opção por não apresentar defesa prévia nem recurso, reconhecendo a infração, o pagamento pode ser efetuado por 60% do valor, em qualquer fase, até o vencimento. O pagamento não implica renúncia ao questionamento administrativo. Não incide cobrança moratória nem restrição enquanto não encerrada a instância administrativa. Encerrada a instância, a multa não paga é acrescida de juros pela Selic e de 1% no mês do pagamento.', '["Desconto: pagamento por oitenta por cento até o vencimento.","Sessenta por cento com adesão ao sistema eletrônico e sem defesa ou recurso.","Sem restrição enquanto durar a instância administrativa.","Juros após o encerramento da instância."]'::jsonb, '["ATUALIZAÇÃO: os descontos de 80% e 60% vieram de lei posterior.","Sem restrição de licenciamento enquanto não encerrada a instância administrativa."]'::jsonb, 'O condutor paga 80% da multa até o vencimento indicado na notificação.', '["Assertiva que fixa em 50% o desconto no pagamento até o vencimento erra: é 80%."]'::jsonb, '[]'::jsonb, '["Art. 282-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-284'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O recurso contra a penalidade imposta é interposto perante a autoridade que imputou a penalidade e tem efeito suspensivo. O recurso intempestivo ou interposto por parte ilegítima não tem efeito suspensivo e, se intempestivo, é arquivado. Recebido o recurso tempestivo, a autoridade o remete à JARI no prazo de dez dias. Para a admissibilidade, não são exigidos documentos emitidos pelo órgão autuador. O recurso deve ser julgado no prazo de vinte e quatro meses, contado do recebimento pelo órgão julgador.', '["Recurso à autoridade que impôs a penalidade.","Efeito suspensivo.","Remessa à JARI em dez dias.","Julgamento em vinte e quatro meses."]'::jsonb, '["Efeito SUSPENSIVO para o recurso tempestivo.","Remessa à JARI em DEZ dias; julgamento em VINTE E QUATRO meses."]'::jsonb, 'O recurso tempestivo suspende a exigibilidade da multa até o julgamento.', '["Assertiva que nega efeito suspensivo ao recurso tempestivo contra a penalidade erra."]'::jsonb, '[]'::jsonb, '["Art. 289-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-285'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O recurso contra a imposição de multa pode ser interposto no prazo legal sem o recolhimento do seu valor. No caso de não provimento, aplica-se o parágrafo único do art. 284. Se o infrator recolher o valor da multa e apresentar recurso, e a penalidade for julgada improcedente, a importância paga é devolvida, atualizada em UFIR ou por índice legal de correção.', '["Recurso sem recolher a multa.","Devolução do valor se julgada improcedente."]'::jsonb, '["Não é necessário pagar para recorrer."]'::jsonb, 'O condutor recorre sem pagar a multa e, se vencer, nada deve.', '["Assertiva que exige o pagamento prévio da multa para recorrer erra."]'::jsonb, '[]'::jsonb, '["Art. 284"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-286'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se a infração for cometida em localidade diversa daquela do licenciamento do veículo, o recurso pode ser apresentado junto ao órgão de trânsito da residência ou do domicílio do infrator. A autoridade que receber o recurso o remete, de pronto, à autoridade que impôs a penalidade, acompanhado das cópias dos prontuários necessários ao julgamento.', '["Recurso no órgão do domicílio do infrator.","Remessa imediata à autoridade autuadora."]'::jsonb, '["Facilita o recurso a quem foi autuado fora do local de licenciamento."]'::jsonb, 'O condutor autuado em outro estado recorre no órgão de sua cidade.', '["Assertiva que obriga o infrator a recorrer no local da infração erra."]'::jsonb, '[]'::jsonb, '["Art. 285"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-287'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Das decisões da JARI cabe recurso, no prazo de trinta dias contado da publicação ou da notificação da decisão. O recurso é interposto, da decisão de não provimento, pelo responsável pela infração e, da decisão de provimento, pela autoridade que impôs a penalidade.', '["Recurso da decisão da JARI em trinta dias.","Legitimados: infrator e autoridade autuadora."]'::jsonb, '["Trinta dias da publicação ou notificação.","A autoridade autuadora pode recorrer do provimento."]'::jsonb, 'Perdendo na JARI, o condutor tem trinta dias para recorrer à instância seguinte.', '["Assertiva que fixa em dez dias o prazo do recurso contra decisão da JARI erra: são trinta dias."]'::jsonb, '[]'::jsonb, '["Art. 289"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-288'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O recurso contra a decisão da JARI deve ser julgado no prazo de vinte e quatro meses, contado do recebimento pelo órgão julgador. Se a penalidade for de órgão da União, o julgamento cabe a colegiado especial integrado pelo Coordenador-Geral da JARI, pelo Presidente da Junta que apreciou o recurso e por mais um Presidente de Junta. Se for de órgão estadual, municipal ou do Distrito Federal, o julgamento cabe ao Cetran e ao Contrandife, respectivamente.', '["Prazo de vinte e quatro meses.","Colegiado especial para penalidades da União.","Cetran e Contrandife para os demais."]'::jsonb, '["Vinte e quatro meses para julgar.","Penalidade da União: colegiado especial; estadual ou municipal: Cetran."]'::jsonb, 'O recurso contra penalidade municipal é julgado pelo Cetran.', '["Assertiva que atribui ao Contran o julgamento de recursos contra penalidades municipais erra: é do Cetran."]'::jsonb, '[]'::jsonb, '["Art. 14"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-289'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O não julgamento dos recursos nos prazos previstos no §6º do art. 285 e no caput do art. 289 enseja a prescrição da pretensão punitiva.', '["Prescrição da pretensão punitiva pelo atraso no julgamento."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior.","Prazos de vinte e quatro meses."]'::jsonb, 'Se o recurso não é julgado no prazo, a multa prescreve.', '["Assertiva que mantém a exigibilidade da multa mesmo com o atraso no julgamento do recurso erra."]'::jsonb, '[]'::jsonb, '["Art. 285"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-289-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Implicam encerramento da instância administrativa de julgamento de infrações e penalidades o julgamento do recurso dos arts. 288 e 289; a não interposição do recurso no prazo legal; e o pagamento da multa, com reconhecimento da infração e requerimento de encerramento do processo, sem apresentação de defesa ou recurso. Esgotados os recursos, as penalidades são cadastradas no Renach.', '["Julgamento do recurso.","Não interposição no prazo.","Pagamento com reconhecimento da infração.","Cadastro no Renach."]'::jsonb, '["Três hipóteses de encerramento da instância administrativa."]'::jsonb, 'Pagar a multa reconhecendo a infração encerra o processo administrativo.', '["Assertiva que não considera encerrada a instância pelo pagamento com reconhecimento da infração erra."]'::jsonb, '[]'::jsonb, '["Art. 288"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-290'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os prazos processuais de que trata o Código não se suspendem, salvo por motivo de força maior devidamente comprovado, nos termos do regulamento do Contran.', '["Prazos não se suspendem.","Exceção: força maior comprovada."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior."]'::jsonb, 'O prazo de defesa só é suspenso por força maior comprovada.', '["Assertiva que suspende os prazos nos feriados prolongados erra."]'::jsonb, '[]'::jsonb, '["Art. 285"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-290-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Aos crimes cometidos na direção de veículos automotores aplicam-se as normas gerais do Código Penal e do Código de Processo Penal, se o capítulo não dispuser de modo diverso, bem como a Lei dos Juizados Especiais, no que couber. Aos crimes de lesão corporal culposa aplicam-se a composição civil, a transação penal e a representação, exceto se o agente estiver sob a influência de álcool ou outra substância psicoativa, participando de corrida ou competição não autorizada, ou transitando em velocidade superior à máxima da via em 50 km/h. Nesses casos, deve ser instaurado inquérito policial.', '["Código Penal e Código de Processo Penal subsidiários.","Juizados Especiais no que couber.","Exceções à transação penal na lesão culposa.","Inquérito policial nas exceções."]'::jsonb, '["Exceções: álcool, racha e excesso de 50 km/h.","Nessas hipóteses, não há benefício dos institutos despenalizadores."]'::jsonb, 'A lesão culposa com excesso de 50 km/h não admite a transação penal.', '["Assertiva que permite a transação penal na lesão culposa cometida sob influência de álcool erra."]'::jsonb, '[]'::jsonb, '["Art. 303"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-291'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A suspensão ou a proibição de se obter a permissão ou a habilitação para dirigir veículo automotor pode ser imposta isolada ou cumulativamente com outras penalidades.', '["Aplicação isolada ou cumulativa."]'::jsonb, '["Pode ser cumulada com outras penas."]'::jsonb, 'O juiz impõe pena de detenção e a suspensão da habilitação ao mesmo tempo.', '["Assertiva que só admite a suspensão aplicada isoladamente erra."]'::jsonb, '[]'::jsonb, '["Art. 293"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-292'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A penalidade de suspensão ou de proibição de se obter a permissão ou a habilitação tem a duração de dois meses a cinco anos. Transitada em julgado a sentença condenatória, o réu é intimado a entregar à autoridade judiciária, em quarenta e oito horas, a Permissão para Dirigir ou a CNH. A penalidade não se inicia enquanto o sentenciado estiver recolhido a estabelecimento prisional.', '["Duração de dois meses a cinco anos.","Entrega do documento em quarenta e oito horas.","Não se inicia durante a prisão."]'::jsonb, '["De dois meses a cinco anos.","Entrega do documento em quarenta e oito horas após o trânsito em julgado."]'::jsonb, 'A suspensão só começa a contar quando o condenado sai da prisão.', '["Assertiva que fixa em dez dias o prazo para entregar a CNH erra: são quarenta e oito horas."]'::jsonb, '[]'::jsonb, '["Art. 307"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-293'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Em qualquer fase da investigação ou da ação penal, havendo necessidade para a garantia da ordem pública, o juiz pode, como medida cautelar, de ofício, a requerimento do Ministério Público ou mediante representação da autoridade policial, decretar, em decisão motivada, a suspensão da permissão ou da habilitação para dirigir ou a proibição de sua obtenção. Da decisão cabe recurso em sentido estrito, sem efeito suspensivo.', '["Medida cautelar para garantir a ordem pública.","Decisão motivada.","Recurso em sentido estrito sem efeito suspensivo."]'::jsonb, '["Cabe de ofício, a requerimento do MP ou por representação da polícia."]'::jsonb, 'O juiz suspende a CNH do réu durante o processo para garantir a ordem pública.', '["Assertiva que exige o trânsito em julgado para a suspensão cautelar erra."]'::jsonb, '[]'::jsonb, '["Art. 293"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-294'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A suspensão para dirigir veículo automotor ou a proibição de se obter a permissão ou a habilitação é sempre comunicada pela autoridade judiciária ao Contran e ao órgão de trânsito do Estado em que o indiciado ou réu for domiciliado ou residente.', '["Comunicação ao Contran e ao órgão estadual."]'::jsonb, '["Comunicação obrigatória."]'::jsonb, 'O juiz comunica ao Contran e ao Detran a suspensão da CNH.', '["Assertiva que dispensa a comunicação ao Contran erra."]'::jsonb, '[]'::jsonb, '["Art. 294"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-295'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se o réu for reincidente na prática de crime previsto no Código, o juiz aplica a penalidade de suspensão da permissão ou habilitação para dirigir veículo automotor, sem prejuízo das demais sanções penais cabíveis.', '["Reincidência impõe a suspensão da habilitação."]'::jsonb, '["Aplicação obrigatória na reincidência."]'::jsonb, 'O reincidente em crime de trânsito tem a habilitação suspensa.', '["Assertiva que torna facultativa a suspensão na reincidência erra."]'::jsonb, '[]'::jsonb, '["Art. 293"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-296'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A multa reparatória consiste no pagamento, mediante depósito judicial em favor da vítima ou de seus sucessores, de quantia calculada com base no §1º do art. 49 do Código Penal, sempre que houver prejuízo material resultante do crime. Não pode ser superior ao valor do prejuízo demonstrado no processo. Aplicam-se os arts. 50 a 52 do Código Penal. Na indenização civil, o valor da multa reparatória é descontado.', '["Depósito judicial em favor da vítima.","Limite do prejuízo demonstrado.","Desconto na indenização civil."]'::jsonb, '["Limitada ao prejuízo demonstrado."]'::jsonb, 'O condenado deposita em favor da vítima o valor do dano ao veículo.', '["Assertiva que permite multa reparatória superior ao prejuízo demonstrado erra."]'::jsonb, '[]'::jsonb, '["Código Penal, art. 49"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-297'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'São circunstâncias que sempre agravam as penalidades dos crimes de trânsito ter o condutor cometido a infração com dano potencial para duas ou mais pessoas ou com grande risco de dano patrimonial a terceiros; utilizando o veículo sem placas, com placas falsas ou adulteradas; sem possuir Permissão para Dirigir ou CNH; com habilitação de categoria diferente; quando sua profissão exigir cuidados especiais com passageiros ou carga; com veículo adulterado em equipamentos ou características que afetem a segurança; ou sobre faixa destinada a pedestres.', '["Sete circunstâncias agravantes.","Placas falsas, falta de habilitação e faixa de pedestres."]'::jsonb, '["Agravantes sempre aplicáveis aos crimes de trânsito."]'::jsonb, 'Cometer o crime sem habilitação agrava a pena.', '["Assertiva que torna facultativa a aplicação das agravantes do art. 298 erra: elas sempre agravam."]'::jsonb, '[]'::jsonb, '["Art. 302"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-298'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ao condutor de veículo, nos casos de sinistros de trânsito que resultem em vítima, não se impõe a prisão em flagrante nem se exige fiança, se prestar pronto e integral socorro àquela.', '["Sem prisão em flagrante nem fiança se prestar pronto e integral socorro."]'::jsonb, '["Depende de pronto e integral socorro."]'::jsonb, 'O condutor que socorre a vítima imediatamente não é preso em flagrante.', '["Assertiva que impede a prisão em flagrante mesmo que o condutor deixe de socorrer erra."]'::jsonb, '[]'::jsonb, '["Art. 304"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-301'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Praticar homicídio culposo na direção de veículo automotor é crime punido com detenção de dois a quatro anos e suspensão ou proibição de se obter a permissão ou a habilitação. A pena aumenta de um terço à metade se o agente não possuir permissão ou habilitação, praticar o crime em faixa de pedestres ou na calçada, deixar de prestar socorro quando possível fazê-lo sem risco pessoal, ou, no exercício de sua profissão, estiver conduzindo veículo de transporte de passageiros. Se o agente conduz sob a influência de álcool ou outra substância psicoativa que determine dependência, a pena é de reclusão de cinco a oito anos, e suspensão ou proibição de obter a habilitação.', '["Detenção de dois a quatro anos e suspensão da habilitação.","Aumento de um terço à metade em quatro hipóteses.","Com álcool: reclusão de cinco a oito anos."]'::jsonb, '["ATUALIZAÇÃO: o §3º (embriaguez, reclusão de cinco a oito anos) foi incluído por lei posterior (Lei Seca ampliada).","Aumento de um terço à metade."]'::jsonb, 'O motorista embriagado que mata no trânsito responde a reclusão de cinco a oito anos.', '["Assertiva que fixa pena de detenção para o homicídio culposo com embriaguez erra: é reclusão."]'::jsonb, '[]'::jsonb, '["Art. 303"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-302'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Praticar lesão corporal culposa na direção de veículo automotor é crime punido com detenção de seis meses a dois anos e suspensão ou proibição de se obter a permissão ou a habilitação. Aumenta-se a pena de um terço à metade nas hipóteses do §1º do art. 302. A pena é de reclusão de dois a cinco anos se o agente conduz com capacidade psicomotora alterada por álcool ou outra substância psicoativa e se do crime resultar lesão corporal de natureza grave ou gravíssima.', '["Detenção de seis meses a dois anos e suspensão da habilitação.","Mesmo aumento do art. 302.","Reclusão de dois a cinco anos com embriaguez e lesão grave ou gravíssima."]'::jsonb, '["ATUALIZAÇÃO: o §2º foi incluído por lei posterior.","Embriaguez com lesão grave ou gravíssima: reclusão."]'::jsonb, 'O condutor alcoolizado que causa lesão grave responde por reclusão de dois a cinco anos.', '["Assertiva que aplica reclusão à lesão culposa comum sem embriaguez erra: é detenção."]'::jsonb, '[]'::jsonb, '["Art. 302"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-303'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Comete crime o condutor que, na ocasião do sinistro, deixa de prestar imediato socorro à vítima ou, não podendo fazê-lo diretamente, por justa causa, deixa de solicitar auxílio da autoridade pública. A pena é de detenção de seis meses a um ano, ou multa, se o fato não constituir elemento de crime mais grave. Incide nas mesmas penas o condutor ainda que sua omissão seja suprida por terceiros ou que se trate de vítima com morte instantânea ou ferimentos leves.', '["Omissão de socorro do condutor.","Detenção de seis meses a um ano, ou multa.","Crime ainda que terceiros socorram ou a vítima morra de imediato."]'::jsonb, '["O crime persiste mesmo com socorro por terceiros ou morte instantânea."]'::jsonb, 'Quem foge sem socorrer a vítima, mesmo que outro a socorra, comete o crime.', '["Assertiva que afasta o crime se terceiros socorrerem a vítima erra."]'::jsonb, '[]'::jsonb, '["Art. 176"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-304'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Comete crime o condutor que se afasta do local do sinistro para fugir à responsabilidade penal ou civil que lhe possa ser atribuída. A pena é de detenção de seis meses a um ano, ou multa.', '["Fuga do local do sinistro.","Detenção de seis meses a um ano, ou multa."]'::jsonb, '["ATUALIZAÇÃO: houve discussão sobre a constitucionalidade do tipo; confira o entendimento do STF."]'::jsonb, 'O condutor que foge do local para não ser responsabilizado comete o crime.', '["Assertiva que classifica a fuga do local como mera infração administrativa erra: também é crime."]'::jsonb, '[]'::jsonb, '["Art. 304"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-305'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Comete crime quem conduz veículo automotor com capacidade psicomotora alterada em razão da influência de álcool ou de outra substância psicoativa que determine dependência. A pena é de detenção de seis meses a três anos, multa e suspensão ou proibição de obter a habilitação. A conduta é constatada por concentração igual ou superior a 6 decigramas de álcool por litro de sangue ou igual ou superior a 0,3 miligrama de álcool por litro de ar alveolar, ou por sinais que indiquem alteração da capacidade psicomotora. A verificação pode ser feita por teste de alcoolemia ou toxicológico, exame clínico, perícia, vídeo, prova testemunhal ou outros meios, observado o direito à contraprova.', '["Detenção de seis meses a três anos, multa e suspensão da habilitação.","Limites: 6 decigramas por litro de sangue ou 0,3 miligrama por litro de ar.","Provas diversas além do bafômetro.","Direito à contraprova."]'::jsonb, '["Limites de 6 decigramas no sangue e 0,3 miligrama no ar alveolar.","Pode ser provado por vídeo, testemunhas e exame clínico."]'::jsonb, 'Concentração de 0,3 mg de álcool por litro de ar configura o crime.', '["Assertiva que exige necessariamente o bafômetro para comprovar o crime erra."]'::jsonb, '[]'::jsonb, '["Art. 165"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-306'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Comete crime quem viola a suspensão ou a proibição de se obter a permissão ou a habilitação para dirigir veículo automotor imposta com fundamento no Código. A pena é de detenção de seis meses a um ano e multa, com nova imposição adicional de idêntico prazo de suspensão ou proibição. Incorre nas mesmas penas o condenado que deixa de entregar, no prazo do §1º do art. 293, a Permissão para Dirigir ou a CNH.', '["Violar a suspensão ou proibição.","Detenção de seis meses a um ano e multa.","Nova imposição de igual prazo.","Deixar de entregar o documento no prazo."]'::jsonb, '["Quem não entrega o documento em quarenta e oito horas também comete o crime."]'::jsonb, 'Quem dirige durante a suspensão judicial comete o crime e sofre nova suspensão.', '["Assertiva que isenta o condenado que não entrega o documento no prazo erra."]'::jsonb, '[]'::jsonb, '["Art. 293"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-307'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Comete crime quem participa, na direção de veículo automotor, em via pública, de corrida, disputa ou competição automobilística ou de exibição ou demonstração de perícia em manobra, não autorizada, gerando situação de risco à incolumidade pública ou privada. A pena é de detenção de seis meses a três anos, multa e suspensão ou proibição de obter a habilitação. Se resultar lesão corporal de natureza grave sem dolo ou assunção do risco, a pena é de reclusão de três a seis anos; se resultar morte, nas mesmas circunstâncias, de cinco a dez anos.', '["Racha e exibição de manobras não autorizados.","Detenção de seis meses a três anos, multa e suspensão.","Lesão grave: reclusão de três a seis anos.","Morte: reclusão de cinco a dez anos."]'::jsonb, '["Qualificadoras: lesão grave (três a seis anos) e morte (cinco a dez anos)."]'::jsonb, 'O racha que causa lesão grave não querida pelo agente tem pena de reclusão de três a seis anos.', '["Assertiva que fixa pena de reclusão de cinco a dez anos para a lesão grave culposa no racha erra: esse é o patamar da morte."]'::jsonb, '[]'::jsonb, '["Art. 173"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-308'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Comete crime quem dirige veículo automotor, em via pública, sem a devida Permissão para Dirigir ou Habilitação ou, ainda, se cassado o direito de dirigir, gerando perigo de dano. A pena é de detenção de seis meses a um ano, ou multa.', '["Dirigir sem habilitação gerando perigo de dano.","Detenção de seis meses a um ano, ou multa."]'::jsonb, '["Exige perigo de dano (crime de perigo concreto)."]'::jsonb, 'Dirigir sem habilitação em via movimentada, gerando perigo, é crime.', '["Assertiva que dispensa o perigo de dano para a configuração do crime erra."]'::jsonb, '[]'::jsonb, '["Art. 162"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-309'
