insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Comete crime quem trafega em velocidade incompatível com a segurança nas proximidades de escolas, hospitais, estações de embarque e desembarque de passageiros, logradouros estreitos, ou onde haja grande movimentação ou concentração de pessoas, gerando perigo de dano. A pena é de detenção de seis meses a um ano, ou multa.', '["Velocidade incompatível perto de escolas e outros locais.","Detenção de seis meses a um ano, ou multa.","Exige perigo de dano."]'::jsonb, '["Exige perigo de dano."]'::jsonb, 'Correr em frente a uma escola, gerando perigo, é crime.', '["Assertiva que dispensa o perigo de dano nesse crime erra."]'::jsonb, '[]'::jsonb, '["Art. 220"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-311'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Comete crime quem inova artificiosamente, em caso de sinistro com vítima, na pendência do procedimento policial preparatório, inquérito policial ou processo penal, o estado de lugar, de coisa ou de pessoa, a fim de induzir a erro o agente policial, o perito ou o juiz. A pena é de detenção de seis meses a um ano, ou multa. O tipo se aplica ainda que não iniciados o procedimento, o inquérito ou o processo quando da inovação.', '["Fraude processual em sinistro com vítima.","Detenção de seis meses a um ano, ou multa.","Aplica-se mesmo antes do início do procedimento."]'::jsonb, '["Alcança a inovação antes mesmo de iniciado o inquérito."]'::jsonb, 'Mudar a posição dos veículos para enganar a perícia é crime.', '["Assertiva que só pune a inovação após a abertura do inquérito erra."]'::jsonb, '[]'::jsonb, '["Art. 279"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-312'
