insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Para os crimes dos arts. 302 a 312, quando o juiz aplicar a substituição da pena privativa de liberdade por pena restritiva de direitos, esta deve ser de prestação de serviço à comunidade ou a entidades públicas, em atividades como trabalho aos fins de semana em equipes de resgate dos bombeiros e outras unidades de atendimento a vítimas de trânsito, trabalho em pronto-socorro da rede pública, trabalho em clínicas ou instituições de recuperação de sinistrados e outras atividades relacionadas a resgate e atendimento.', '["Substituição por prestação de serviço relacionada a vítimas de trânsito.","Resgate, pronto-socorro e recuperação de sinistrados."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior."]'::jsonb, 'O condenado cumpre pena restritiva em equipe de resgate dos bombeiros.', '["Assertiva que permite qualquer pena restritiva de direitos aos crimes dos arts. 302 a 312 erra."]'::jsonb, '[]'::jsonb, '["Art. 312-B"]'::jsonb, 'under_review', 'claude'
