insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Aos crimes do §3º do art. 302 e do §2º do art. 303 não se aplica o disposto no inciso I do caput do art. 44 do Código Penal, ou seja, a substituição da pena privativa de liberdade por restritiva de direitos nos crimes cometidos com violência ou grave ameaça.', '["Afasta a substituição da pena nos crimes mais graves com embriaguez."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior.","Alcança homicídio e lesão grave culposos com embriaguez."]'::jsonb, 'O condutor alcoolizado que mata no trânsito não tem a pena substituída por restritiva de direitos.', '["Assertiva que permite a substituição da pena em todos os crimes de trânsito erra."]'::jsonb, '[]'::jsonb, '["Art. 302"]'::jsonb, 'under_review', 'claude'
