insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Contran tem prazo de duzentos e quarenta dias da publicação do Código para expedir as resoluções necessárias à sua melhor execução e revisar todas as resoluções anteriores, dando prioridade às que visam diminuir o número de sinistros e assegurar a proteção de pedestres. As resoluções do Contran existentes até a data de publicação do Código continuam em vigor naquilo em que não conflitem com ele.', '["Prazo de duzentos e quarenta dias.","Resoluções anteriores vigoram se não conflitarem."]'::jsonb, '["Dispositivo transitório."]'::jsonb, 'Resolução anterior ao Código só vale na parte que não o contraria.', '["Assertiva que revoga todas as resoluções anteriores ao Código erra."]'::jsonb, '[]'::jsonb, '["Art. 12"]'::jsonb, 'under_review', 'claude'
