select u.id, u.content_sha256, 'O Ministério da Educação, mediante proposta do Contran, deve, no prazo de duzentos e quarenta dias contado da publicação do Código, estabelecer o currículo com conteúdo programático relativo à segurança e à educação de trânsito.', '["Prazo de duzentos e quarenta dias.","Currículo de segurança e educação de trânsito."]'::jsonb, '["Dispositivo transitório."]'::jsonb, 'O currículo escolar inclui conteúdo de educação para o trânsito.', '["Assertiva que atribui ao Contran, e não ao MEC, a fixação do currículo erra."]'::jsonb, '[]'::jsonb, '["Art. 76"]'::jsonb, 'under_review', 'claude'
