insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As repartições de trânsito conservam por, no mínimo, cinco anos os documentos relativos à habilitação de condutores, ao registro e ao licenciamento de veículos e aos autos de infração de trânsito. Esses documentos podem ser gerados, tramitados, arquivados e armazenados eletronicamente, desde que assegurada a autenticidade, a fidedignidade, a confiabilidade e a segurança, sendo válidos para todos os efeitos e dispensada a guarda física. O Contran regulamenta o procedimento.', '["Guarda mínima de cinco anos.","Documentos eletrônicos válidos.","Regulamentação pelo Contran."]'::jsonb, '["Mínimo de cinco anos.","ATUALIZAÇÃO: arquivamento digital foi admitido por lei posterior."]'::jsonb, 'O Detran mantém digitalmente os autos de infração por no mínimo cinco anos.', '["Assertiva que fixa em dois anos o prazo mínimo de guarda dos documentos erra: são cinco anos."]'::jsonb, '[]'::jsonb, '["Art. 280"]'::jsonb, 'under_review', 'claude'
