insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O veículo apreendido ou removido a qualquer título e não reclamado por seu proprietário dentro do prazo de sessenta dias, contado da data do recolhimento, é avaliado e levado a leilão, preferencialmente eletrônico. Publicado o edital, a preparação pode ser iniciada após trinta dias do recolhimento, classificando-se o veículo em conservado, se apresenta condições de segurança para trafegar, ou sucata, se não está apto a trafegar. Se não houver oferta igual ou superior à avaliação, o lote vai ao leilão seguinte e é arrematado pelo maior lance.', '["Prazo de sessenta dias para reclamar.","Leilão preferencialmente eletrônico.","Classificação: conservado ou sucata."]'::jsonb, '["Sessenta dias para reclamar; preparação do leilão após trinta dias.","ATUALIZAÇÃO: a redação foi alterada por lei posterior."]'::jsonb, 'O carro não reclamado em sessenta dias vai a leilão.', '["Assertiva que fixa em noventa dias o prazo para reclamar o veículo removido erra: são sessenta dias."]'::jsonb, '[]'::jsonb, '["Art. 279-A"]'::jsonb, 'under_review', 'claude'
