insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os condutores dos veículos de aluguel e de escolares, para exercerem suas atividades, devem apresentar previamente certidão negativa do registro de distribuição criminal relativamente aos crimes de homicídio, roubo, estupro e corrupção de menores, renovável a cada cinco anos, junto ao órgão responsável pela concessão ou autorização.', '["Certidão negativa criminal prévia.","Crimes específicos: homicídio, roubo, estupro e corrupção de menores.","Renovação a cada cinco anos."]'::jsonb, '["Renovação a cada cinco anos."]'::jsonb, 'O motorista de táxi apresenta a certidão negativa para exercer a atividade.', '["Assertiva que dispensa a certidão negativa para condutores de transporte escolar erra."]'::jsonb, '[]'::jsonb, '["Art. 135"]'::jsonb, 'under_review', 'claude'
