insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os estabelecimentos onde se executam reformas ou recuperação de veículos e os que compram, vendem ou desmontam veículos, usados ou não, são obrigados a possuir livros de registro de seu movimento de entrada e saída e de uso de placas de experiência, conforme modelos aprovados pelos órgãos de trânsito. Os livros indicam a data de entrada, os dados do proprietário ou vendedor, a data da saída ou baixa, os dados do comprador, as características do veículo e o número da placa de experiência.', '["Livros de registro obrigatórios.","Entrada, saída e placas de experiência.","Dados do proprietário, do comprador e do veículo."]'::jsonb, '["Aplica-se a oficinas e a quem compra, vende ou desmonta veículos."]'::jsonb, 'A oficina anota a entrada e a saída de cada veículo em livro próprio.', '["Assertiva que dispensa o livro de registro nos estabelecimentos que desmontam veículos erra."]'::jsonb, '[]'::jsonb, '["Art. 126"]'::jsonb, 'under_review', 'claude'
