select u.id, u.content_sha256, 'Até a nomeação e posse dos membros dos colegiados destinados ao julgamento dos recursos administrativos previstos no Código, o julgamento dos recursos ficou a cargo dos órgãos então existentes.', '["Regra transitória do julgamento de recursos."]'::jsonb, '["Dispositivo transitório."]'::jsonb, 'Os órgãos existentes julgaram recursos até a instalação das JARI.', '["Assertiva que torna permanente a competência dos órgãos antigos para julgar recursos erra."]'::jsonb, '[]'::jsonb, '["Art. 16"]'::jsonb, 'under_review', 'claude'
