insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os órgãos e entidades do Sistema Nacional de Trânsito proporcionam aos membros do Contran, dos Cetran e do Contrandife, em serviço, todas as facilidades para o cumprimento de sua missão, fornecendo as informações que solicitarem, permitindo-lhes inspecionar a execução de serviços e atendendo prontamente as suas requisições.', '["Facilidades e informações aos membros dos conselhos.","Inspeção de serviços e atendimento a requisições."]'::jsonb, '["Dever de colaboração dos órgãos do sistema."]'::jsonb, 'O órgão de trânsito fornece os dados que o Cetran requisitar.', '["Assertiva que isenta os órgãos do sistema de atender às requisições dos conselhos erra."]'::jsonb, '[]'::jsonb, '["Art. 14"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-332'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Contran estabeleceria, em até cento e vinte dias após a nomeação de seus membros, as disposições dos arts. 91 e 92, a serem atendidas pelos órgãos executivos de trânsito e rodoviários para exercerem suas competências. Os órgãos já existentes teriam prazo de um ano, após a edição das normas, para se adequarem; os a serem criados exerceriam suas competências em cumprimento às exigências do Contran, acompanhados pelo respectivo Cetran.', '["Cento e vinte dias para o Contran.","Um ano para adequação dos órgãos existentes."]'::jsonb, '["Dispositivo transitório."]'::jsonb, 'Os órgãos existentes tiveram um ano para se adequar às normas do Contran.', '["Assertiva que fixa em dois anos o prazo de adequação dos órgãos existentes erra: era de um ano."]'::jsonb, '[]'::jsonb, '["Art. 91"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-333'
