insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As montadoras, encarroçadoras, importadores e fabricantes, ao comercializarem veículos automotores de qualquer categoria e ciclos, são obrigados a fornecer, no ato da comercialização, manual com as normas de circulação, infrações, penalidades, direção defensiva, primeiros socorros e Anexos do Código.', '["Fornecimento de manual com normas de trânsito.","Direção defensiva e primeiros socorros."]'::jsonb, '["Obrigação do fabricante ou importador na comercialização."]'::jsonb, 'O comprador do veículo recebe o manual com normas de trânsito.', '["Assertiva que isenta fabricantes da entrega do manual de trânsito erra."]'::jsonb, '[]'::jsonb, '["Art. 77-B"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-338'
