insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As competências dos arts. 21, XV, e 24, XXII, passaram a ser atribuídas aos órgãos ou entidades ali descritos a partir de 1º de janeiro de 2024. Até 31 de dezembro de 2023, essas competências foram exercidas pelos órgãos executivos de trânsito dos Estados e do Distrito Federal.', '["Transferência de competências em 1º de janeiro de 2024.","Regra provisória até 31 de dezembro de 2023."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior.","Dispositivo de transição, já cumprido."]'::jsonb, 'A partir de 2024, as competências passaram aos órgãos descritos nos arts. 21 e 24.', '["Assertiva que mantém a competência dos Estados após 2023 erra."]'::jsonb, '[]'::jsonb, '["Art. 21"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-338-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Poder Executivo foi autorizado a abrir crédito especial de R$ 264.954,00 em favor do ministério ou órgão responsável pela coordenação máxima do Sistema Nacional de Trânsito, para atender às despesas de implantação do Código.', '["Crédito especial para implantação do Código."]'::jsonb, '["Dispositivo de eficácia esgotada."]'::jsonb, 'A verba especial financiou a implantação do Código.', '["Assertiva que torna esse crédito uma despesa permanente do sistema erra."]'::jsonb, '[]'::jsonb, '["Art. 9º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-339'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Código entrou em vigor cento e vinte dias após a data de sua publicação.', '["Vigência após cento e vinte dias."]'::jsonb, '["Dispositivo histórico."]'::jsonb, 'O Código só passou a valer depois do período de vacância.', '["Assertiva que fixa vigência imediata do Código erra: foram cento e vinte dias."]'::jsonb, '[]'::jsonb, '["Art. 341"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-340'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ficaram revogadas as leis, decretos-leis e artigos listados no dispositivo, que tratavam do trânsito antes do Código atual.', '["Revogação das leis anteriores sobre trânsito."]'::jsonb, '["Dispositivo histórico."]'::jsonb, 'O Código substituiu o regime de trânsito anterior.', '["Assertiva que mantém em vigor o antigo Código Nacional de Trânsito erra."]'::jsonb, '[]'::jsonb, '["Art. 340"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-341'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Anexo I reúne as definições usadas pelo Código, como acostamento, agente da autoridade de trânsito, automóvel (até oito pessoas, exclusive o condutor), bicicleta, calçada, caminhão (peso bruto total acima de 3.500 kg), ciclomotor (até 50 cm³, 4 kW e 50 km/h), cruzamento, estacionamento, estrada (via rural não pavimentada), rodovia (via rural pavimentada), parada, ultrapassagem, sinistro de trânsito, veículo de coleção (mais de trinta anos) e os tipos de vias urbanas.', '["Definições de agentes, vias, veículos e manobras.","Automóvel: até oito pessoas, exclusive o condutor.","Ciclomotor: até 50 cm³, 4 kW e 50 km/h.","Estrada = via rural não pavimentada; rodovia = via rural pavimentada.","Estacionamento x parada.","Veículo de coleção: fabricado há mais de trinta anos."]'::jsonb, '["ATUALIZAÇÃO: o texto adota o termo \"sinistro de trânsito\" e inclui definições de agente de trânsito e veículo de coleção por leis recentes.","Parada = tempo estritamente necessário ao embarque ou desembarque; estacionamento = tempo superior.","Microônibus: até vinte passageiros; ônibus: mais de vinte."]'::jsonb, 'Parar para o passageiro descer é parada; ficar além do necessário é estacionamento.', '["Assertiva que define a estrada como via rural pavimentada erra: é via rural não pavimentada, e a rodovia é a pavimentada."]'::jsonb, '[{"termo":"Sinistro de trânsito","significado":"Evento com dano ao veículo, à carga ou a pessoas, em que ao menos uma parte está em movimento."},{"termo":"Via de trânsito rápido","significado":"Via com acessos especiais, sem interseções em nível e sem travessia de pedestres em nível."}]'::jsonb, '["Art. 4º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'anexo-1'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();
